import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/variable_zod.js';

// ==================== 武器部件 ====================
const 武器部件 = z
  .object({
    部件类型: z.literal('武器').prefault('武器'),
    武器名: z.string().prefault(''),
    武器类型: z.enum(['近战', '动能', '能量', '爆破', '导弹']).prefault('动能'),
    破甲等级: z.enum(['TIER1', 'TIER2', 'TIER3', 'TIER4', 'TIER5', 'TIER6']).prefault('TIER1'),
    固定伤害: z.coerce.number().prefault(0),
    弹药量: z.coerce.number().prefault(0), // 0 = 无限/近战
    最优距离区间: z
      .object({
        最小: z.coerce.number().prefault(1),
        最大: z.coerce.number().prefault(4),
      })
      .prefault({}),
    制造商: z.string().prefault(''),
    重量: z.coerce.number().prefault(0),
  })
  .prefault({});

// ==================== 护盾发生器部件 ====================
const 护盾发生器部件 = z
  .object({
    部件类型: z.literal('护盾发生器').prefault('护盾发生器'),
    护盾名: z.string().prefault(''),
    护盾类型: z.enum(['脉冲护盾', '谐波护盾', '珂若尔护盾']).prefault('脉冲护盾'),
    护盾上限: z.coerce.number().prefault(0),
    制造商: z.string().prefault(''),
    重量: z.coerce.number().prefault(0),
  })
  .prefault({});

// LB 槽：武器优先（空槽默认为空武器），也可装护盾发生器
const LB槽 = z.union([武器部件, 护盾发生器部件]).prefault({});

// ==================== 帧架部件 ====================
const 头部部件 = z
  .object({
    部件类型: z.literal('头部').prefault('头部'),
    部件名: z.string().prefault(''),
    制造商: z.string().prefault(''),
    重量: z.coerce.number().prefault(0),
    先攻加值: z.coerce.number().prefault(0), // 影响先攻骰加值，取代旧"观测效益"
  })
  .prefault({});

const 核心部件 = z
  .object({
    部件类型: z.literal('核心').prefault('核心'),
    部件名: z.string().prefault(''),
    制造商: z.string().prefault(''),
    重量: z.coerce.number().prefault(0),
    装甲等级: z.enum(['TIER1', 'TIER2', 'TIER3', 'TIER4', 'TIER5', 'TIER6']).prefault('TIER1'),
    装甲上限: z.coerce.number().prefault(100),
    结构上限: z.coerce.number().prefault(100),
    ACS上限: z.coerce.number().prefault(100), // 韧性：越高越难被破防
  })
  .prefault({});

const 手部部件 = z
  .object({
    部件类型: z.literal('手部').prefault('手部'),
    部件名: z.string().prefault(''),
    制造商: z.string().prefault(''),
    重量: z.coerce.number().prefault(0),
    近战伤害加值: z.coerce.number().prefault(0), // 影响LA近战伤害
    武器重量上限: z.coerce.number().prefault(50), // RA/LA可挂载的最大武器重量
  })
  .prefault({});

const 足部部件 = z
  .object({
    部件类型: z.literal('足部').prefault('足部'),
    部件名: z.string().prefault(''),
    制造商: z.string().prefault(''),
    重量: z.coerce.number().prefault(0),
    移动效率: z.coerce.number().prefault(1), // 每次移动动作改变的Ⓓ档位数
  })
  .prefault({});

// ==================== 系统部件 ====================
const 推进器部件 = z
  .object({
    部件类型: z.literal('推进器').prefault('推进器'),
    部件名: z.string().prefault(''),
    制造商: z.string().prefault(''),
    重量: z.coerce.number().prefault(0),
    总出力: z.coerce.number().prefault(100), // 参与推重比计算：推重比 = 总出力 ÷ 机体总重
  })
  .prefault({});

const FCS部件 = z
  .object({
    部件类型: z.literal('FCS').prefault('FCS'),
    部件名: z.string().prefault(''),
    制造商: z.string().prefault(''),
    重量: z.coerce.number().prefault(0),
    战斗风格: z.string().prefault('均衡战线型'), // 定义整体战法，如"近战特化""远距狙击"
    最优距离区间: z
      .object({
        最小: z.coerce.number().prefault(1),
        最大: z.coerce.number().prefault(4),
      })
      .prefault({}),
    特殊效果: z.string().prefault(''), // 战斗风格赋予的特殊加值/解锁动作描述
  })
  .prefault({});

const 发动机部件 = z
  .object({
    部件类型: z.literal('发动机').prefault('发动机'),
    部件名: z.string().prefault(''),
    制造商: z.string().prefault(''),
    重量: z.coerce.number().prefault(0),
    总能源: z.coerce.number().prefault(100), // 供电量，决定能源武器可用性
  })
  .prefault({});

const 扩充机能部件 = z
  .object({
    部件类型: z.literal('扩充机能').prefault('扩充机能'),
    机能名: z.string().prefault(''),
    效果描述: z.string().prefault(''), // 强力被动特质描述，如"精神框架：好感度≥80时同步率上限+10"
    重量: z.coerce.number().prefault(0),
  })
  .prefault({});

// ==================== 部件构建（12槽）====================
const 部件构建 = z
  .object({
    RA: 武器部件, // 右手武器
    LA: 武器部件, // 左手武器（近战Blade装备此处）
    RB: 武器部件, // 右肩武器（大型武装，含导弹）
    LB: LB槽,    // 左肩武器（大型武装 或 护盾发生器）
    头部: 头部部件,
    核心: 核心部件,
    手部: 手部部件,
    足部: 足部部件,
    推进器: 推进器部件,
    FCS: FCS部件,
    发动机: 发动机部件,
    扩充机能: 扩充机能部件,
  })
  .prefault({});

// ==================== 机体整合数值（配装派生，换装时更新）====================
const 机体整合数值 = z
  .object({
    机体类型: z.enum(['球形', '人形', '逆足', '生物', '半履带', '多足']).prefault('人形'),
    装甲等级: z.enum(['TIER1', 'TIER2', 'TIER3', 'TIER4', 'TIER5', 'TIER6']).prefault('TIER1'),
    装甲上限: z.coerce.number().prefault(100),
    结构上限: z.coerce.number().prefault(100),
    ACS上限: z.coerce.number().prefault(100),
    护盾上限: z.coerce.number().prefault(0), // LB装护盾时>0，无护盾时=0
    机体总重: z.coerce.number().prefault(0), // 12件部件重量之和
    推重比: z.coerce.number().prefault(2.0), // 推进器总出力 ÷ 机体总重
    推重加值: z.coerce.number().prefault(2), // 由推重比档位决定，影响命中/闪避
    先攻加值: z.coerce.number().prefault(0), // 来自头部，影响先攻骰
  })
  .prefault({});

// ==================== 可用部件联合类型（机库库存用）====================
const 可用部件 = z.union([
  武器部件,
  护盾发生器部件,
  头部部件,
  核心部件,
  手部部件,
  足部部件,
  推进器部件,
  FCS部件,
  发动机部件,
  扩充机能部件,
]);

// ==================== 主Schema定义 ====================
export const Schema = z.object({
  全局信息: z
    .object({
      物理位置: z.string().prefault(''),
      时间: z.string().prefault(''),
      当前章节: z.enum(['序章', '第一章', '第二章', '第三章', '第四章', '终章']).prefault('序章'),
    })
    .prefault({}),

  主角: z
    .object({
      驾驶属性: z
        .object({
          APM: z.coerce.number().prefault(150), // 操作每分钟，决定驾驶基础值
          KRL等级: z.coerce
            .number()
            .transform(v => _.clamp(v, 1, 10))
            .prefault(1),
          神经同步率: z.coerce
            .number()
            .transform(v => _.clamp(v, 0, 100))
            .prefault(60),
          驾驶加值: z.coerce.number().prefault(0), // 由APM+KRL+同步率计算，影响命中
        })
        .prefault({}),

      机甲状态: z
        .object({
          // 当前驾驶机甲的实时损伤状态，跨场景持久化
          结构值: z.coerce.number().transform(v => Math.max(v, 0)).prefault(100),
          结构上限: z.coerce.number().prefault(100),
          装甲值: z.coerce.number().transform(v => Math.max(v, 0)).prefault(100),
          装甲上限: z.coerce.number().prefault(100),
          ACS值: z.coerce.number().transform(v => _.clamp(v, 0, 9999)).prefault(0), // 当前ACS应变积累，战斗后重置
          ACS上限: z.coerce.number().prefault(100),
          护盾值: z.coerce.number().transform(v => Math.max(v, 0)).prefault(0),
          护盾上限: z.coerce.number().prefault(0), // LB无护盾时=0
        })
        .prefault({}),

      驾驶员档案: z
        .object({
          资金_CAGE: z.coerce.number().transform(v => Math.max(v, 0)).prefault(5000),
          当前经验: z.coerce.number().transform(v => Math.max(v, 0)).prefault(0),
          升级所需经验: z.coerce.number().prefault(100),
        })
        .prefault({}),
    })
    .prefault({}),

  机甲泊位: z
    .object({
      当前驾驶机甲: z.string().prefault(''), // 当前出击机甲名称
      泊位: z
        .record(
          z.string().describe('机甲名'),
          z
            .object({
              部件构建: 部件构建,
              机体整合数值: 机体整合数值,
            })
            .prefault({}),
        )
        .prefault({}),
    })
    .prefault({}),

  交感同操: z
    .object({
      启用状态: z.boolean().prefault(false),
      inputer: z
        .object({
          姓名: z.string().prefault(''),
          KRL等级: z.coerce
            .number()
            .transform(v => _.clamp(v, 1, 10))
            .prefault(1),
          是否生物机甲: z.boolean().prefault(false),
        })
        .prefault({}),
      outputer: z
        .object({
          姓名: z.string().prefault(''),
          APM值: z.coerce.number().prefault(0),
        })
        .prefault({}),
      接触方式: z.enum(['皮肤接触', '粘膜接触', '性交']).prefault('皮肤接触'),
    })
    .prefault({}),

  红颜通讯: z
    .record(
      z.string().describe('角色ID'),
      z.object({
        角色名称: z.string().prefault(''),
        阵营: z.string().prefault(''),
        好感度: z.coerce
          .number()
          .transform(v => _.clamp(v, 0, 100))
          .prefault(0),
        关系阶段: z.enum(['陌生人', '相识', '熟识', '信任', '亲密', '恋人']).prefault('陌生人'),
        默契度: z.coerce
          .number()
          .transform(v => _.clamp(v, 0, 100))
          .prefault(0),
        解锁对话: z.array(z.string()).prefault([]),
        未读消息数: z.coerce.number().prefault(0),
        最后通讯时间: z.string().prefault(''),
        备注: z.string().prefault(''),
      }),
    )
    .prefault({}),

  机库: z
    .object({
      机库整备设备: z.record(z.string().describe('设备名'), z.string().describe('设备描述')).prefault({}),
      可用机甲部件: z.record(z.string().describe('部件名'), 可用部件).prefault({}),
    })
    .prefault({}),

  任务面板: z
    .record(
      z.string().describe('任务ID'),
      z.object({
        任务名称: z.string().prefault(''),
        任务类型: z.enum(['普通', '困难', '极难']).prefault('普通'),
        阵营: z.string().prefault(''),
        目标列表: z.array(z.string()).prefault([]),
        奖励经验: z.coerce.number().prefault(0),
        奖励资金: z.coerce.number().prefault(0),
        奖励物品: z.array(z.string()).prefault([]),
        进行状态: z.enum(['未开始', '进行中', '已完成', '失败']).prefault('未开始'),
        截止时间: z.string().prefault(''),
      }),
    )
    .prefault({}),
});

$(() => {
  registerMvuSchema(Schema);
});

/**
 * AC6 动态世界书管理
 * 世界书：-装甲核心
 * 依据 MVU「全局信息.当前章节」「任务面板.*.任务名称 / 进行状态」与最近 1 条聊天正文的关键词，直接设置条目 enabled。
 */
(function () {
  'use strict';

  const WORLDBOOK_NAME = '-装甲核心';
  /** 扫描最近几条聊天消息的正文做关键词 failsafe（1=仅最后一楼，与 master「1 楼层」一致） */
  const SCAN_LAST_MESSAGES = 1;
  const DEBOUNCE_MS = 400;
  const DEBUG = false;

  /** 进行状态：变量侧认为「仍与任务相关」（若希望「未开始」的下一条也走变量通道，可加入 '未开始'） */
  const QUEST_ACTIVE = new Set(['进行中']);

  /**
   * 按章节配置：outline=章节目录条目名；tasks=任务明细
   * 新增章节时在此追加即可。
   */
  const CHAPTER_CONFIG = {
    第一章: {
      outlineEntry: '第一章',
      tasks: [
        {
          entryName: '第一章-偷渡',
          keywords: ['偷渡'],
          taskMatchers: ['偷渡'],
        },
        {
          entryName: '第一章-击破测试AC',
          keywords: ['击破测试AC'],
          taskMatchers: ['击破测试AC'],
        },
        {
          entryName: '第一章-多重水坝袭击',
          keywords: ['多重水坝袭击'],
          taskMatchers: ['多重水坝袭击'],
        },
        {
          entryName: '第一章-武装开采舰「阔步者」',
          keywords: ['武装开采舰「阔步者」', '阔步者'],
          taskMatchers: ['武装开采舰', '阔步者', '武装开采舰「阔步者」'],
        },
        {
          entryName: '第一章-越墙',
          keywords: ['越墙'],
          taskMatchers: ['越墙'],
        },
        {
          entryName: '第一章-调查BAWS第二工厂 / 妨碍强制监察',
          keywords: ['调查BAWS第二工厂', '妨碍强制监察'],
          taskMatchers: ['调查BAWS第二工厂', '妨碍强制监察', 'BAWS第二工厂', '第二工厂'],
        },
        {
          entryName: '第一章-袭击监视点',
          keywords: ['袭击监视点'],
          taskMatchers: ['袭击监视点'],
        },
      ],
    },

    第二章: {
      outlineEntry: '第二章',
      tasks: [
        {
          entryName: '第二章-入侵网格086',
          keywords: ['入侵网格086'],
          taskMatchers: ['入侵网格086'],
        },
        {
          entryName: '第二章-跨海',
          keywords: ['跨海'],
          taskMatchers: ['跨海'],
        },
      ],
    },

    第三章: {
      outlineEntry: '第三章',
      tasks: [
        {
          entryName: '第三章-调查无人海上都市',
          keywords: ['调查无人海上都市'],
          taskMatchers: ['调查无人海上都市'],
        },
        {
          entryName: '第三章-除掉或俘虏晚钟7号',
          keywords: ['除掉或俘虏晚钟7号'],
          taskMatchers: ['除掉或俘虏晚钟7号', '晚钟7号'],
        },
        {
          entryName: '第三章-支援大型飞弹发射',
          keywords: ['支援大型飞弹发射'],
          taskMatchers: ['支援大型飞弹发射', '大型飞弹发射'],
        },
        {
          entryName: '第三章-袭击旧宇宙港',
          keywords: ['袭击旧宇宙港'],
          taskMatchers: ['袭击旧宇宙港', '旧宇宙港'],
        },
        {
          entryName: '第三章-除掉诚恳布鲁杜',
          keywords: ['除掉诚恳布鲁杜'],
          taskMatchers: ['除掉诚恳布鲁杜', '诚恳布鲁杜', '布鲁杜'],
        },
        {
          entryName: '第三章-击破冰雪蠕虫',
          keywords: ['击破冰雪蠕虫', '冰雪蠕虫'],
          taskMatchers: ['击破冰雪蠕虫', '冰雪蠕虫'],
        },
        {
          entryName: '第三章-旧宇宙港防卫',
          keywords: ['旧宇宙港防卫'],
          taskMatchers: ['旧宇宙港防卫', '旧宇宙港'],
        },
      ],
    },

    第四章: {
      outlineEntry: '第四章',
      tasks: [
        {
          entryName: '第四章-探查地底-深度1',
          keywords: ['探查地底-深度1', '探查地底'],
          taskMatchers: ['探查地底-深度1', '探查地底'],
        },
        {
          entryName: '第四章-探查地底-深度2',
          keywords: ['探查地底-深度2'],
          taskMatchers: ['探查地底-深度2', '探查地底'],
        },
        {
          entryName: '第四章-探查地底-深度3',
          keywords: ['探查地底-深度3'],
          taskMatchers: ['探查地底-深度3', '探查地底'],
        },
        {
          entryName: '第四章-拦截赤枪部队',
          keywords: ['拦截赤枪部队'],
          taskMatchers: ['拦截赤枪部队', '赤枪部队'],
        },
        {
          entryName: '第四章-伏击晚钟部队',
          keywords: ['伏击晚钟部队'],
          taskMatchers: ['伏击晚钟部队', '晚钟部队'],
        },
        {
          entryName: '第四章-探索未至领域',
          keywords: ['探索未至领域'],
          taskMatchers: ['探索未至领域', '未至领域'],
        },
        {
          entryName: '第四章-抵达珂若尔汇聚地',
          keywords: ['抵达珂若尔汇聚地'],
          taskMatchers: ['抵达珂若尔汇聚地', '珂若尔汇聚地'],
        },
      ],
    },

    终章: {
      outlineEntry: '第五章',
      tasks: [
        {
          entryName: '终章-逃脱',
          keywords: ['逃脱'],
          taskMatchers: ['逃脱'],
        },
        {
          entryName: '终章-接管无人都市',
          keywords: ['接管无人都市'],
          taskMatchers: ['接管无人都市', '无人都市'],
        },
        {
          entryName: '终章-突破卡门线',
          keywords: ['突破卡门线'],
          taskMatchers: ['突破卡门线', '卡门线'],
        },
        {
          entryName: '终章-结局',
          keywords: ['结局'],
          taskMatchers: ['结局'],
        },
      ],
    },
  };

  const MANAGED_NAMES = new Set();
  Object.values(CHAPTER_CONFIG).forEach(cfg => {
    MANAGED_NAMES.add(cfg.outlineEntry);
    cfg.tasks.forEach(t => MANAGED_NAMES.add(t.entryName));
  });

  let debounceTimer = null;
  let running = false;

  function log(...args) {
    if (DEBUG) console.log('[AC6世界书]', ...args);
  }

  function stripNoise(text) {
    if (!text) return '';
    return String(text)
      .replace(/\[动态世界书\][^\n]*/g, '')
      .replace(/【[^】]*】/g, '')
      .replace(/<UpdateVariable>[\s\S]*?<\/UpdateVariable>/g, '')
      .replace(/```mvu_update[\s\S]*?```/g, '')
      .replace(/```[\s\S]*?```/g, '')
      .trim();
  }

  function getRecentChatPlainText(lastN) {
    const n = Math.max(1, lastN | 0);
    try {
      const lastId = getLastMessageId();
      if (lastId < 0) return '';
      const start = Math.max(0, lastId - (n - 1));
      const slice = getChatMessages(`${start}-${lastId}`);
      if (!slice?.length) return '';
      return slice
        .map(m => stripNoise(m.message || ''))
        .filter(Boolean)
        .join('\n');
    } catch (e) {
      log('获取聊天正文失败', e);
      return '';
    }
  }

  function getStatData() {
    try {
      const mvu = Mvu.getMvuData({ type: 'message', message_id: -1 });
      return _.get(mvu, 'stat_data', null);
    } catch (e) {
      log('读取 MVU 失败', e);
      return null;
    }
  }

  function collectActiveTaskNames(statData) {
    const panel = _.get(statData, '任务面板', {});
    const names = [];
    if (!panel || typeof panel !== 'object') return names;
    for (const id of Object.keys(panel)) {
      const q = panel[id];
      const status = q?.进行状态;
      if (!QUEST_ACTIVE.has(status)) continue;
      const name = String(q?.任务名称 ?? '').trim();
      if (name) names.push(name);
    }
    return names;
  }

  function variableMatchesTask(taskMatchers, activeTaskNames) {
    for (const taskName of activeTaskNames) {
      for (const m of taskMatchers) {
        if (!m) continue;
        if (taskName === m) return true;
        if (taskName.includes(m) || m.includes(taskName)) return true;
      }
    }
    return false;
  }

  function keywordMatches(text, keywords) {
    if (!text) return false;
    return keywords.some(k => k && text.includes(k));
  }

  /**
   * @returns {Record<string, boolean>}
   */
  function computeDesiredEnabled(statData, recentText) {
    const chapter = String(_.get(statData, '全局信息.当前章节', '') || '').trim();
    const activeTasks = collectActiveTaskNames(statData);
    const desired = {};

    for (const [chKey, cfg] of Object.entries(CHAPTER_CONFIG)) {
      const inChapter = chapter === chKey;
      desired[cfg.outlineEntry] = inChapter;

      for (const task of cfg.tasks) {
        if (!inChapter) {
          desired[task.entryName] = false;
          continue;
        }
        const byVar = variableMatchesTask(task.taskMatchers, activeTasks);
        const byKey = keywordMatches(recentText, task.keywords);
        desired[task.entryName] = byVar || byKey;
      }
    }

    log('章节=', chapter, '任务=', activeTasks, '扫描文本长度=', recentText.length);
    return desired;
  }

  async function applyWorldbook() {
    if (running) return;
    running = true;
    try {
      await waitGlobalInitialized('Mvu');
      const stat = getStatData();
      const recent = getRecentChatPlainText(SCAN_LAST_MESSAGES);
      const desired = computeDesiredEnabled(stat, recent);

      let changed = 0;
      await updateWorldbookWith(WORLDBOOK_NAME, entries => {
        for (const entry of entries) {
          const name = entry.name || '';
          if (!MANAGED_NAMES.has(name)) continue;
          const want = !!desired[name];
          if (entry.enabled !== want) {
            entry.enabled = want;
            changed++;
            log(`${want ? '开启' : '关闭'}: ${name}`);
          }
        }
        return entries;
      });

      if (DEBUG && changed > 0 && typeof toastr !== 'undefined') {
        toastr.info(`已更新 ${changed} 条条目`, 'AC6 世界书');
      }
    } catch (e) {
      console.error('[AC6世界书] 更新失败', e);
      if (DEBUG && typeof toastr !== 'undefined') {
        toastr.error(String(e?.message || e), 'AC6 世界书');
      }
    } finally {
      running = false;
    }
  }

  function scheduleApply() {
    if (debounceTimer) clearTimeout(debounceTimer);
    debounceTimer = setTimeout(() => {
      debounceTimer = null;
      errorCatched(applyWorldbook)();
    }, DEBOUNCE_MS);
  }

  $(() => {
