      });
      eventOn(tavern_events.CHAT_CHANGED, () => {
        log('CHAT_CHANGED');
        scheduleApply();
      });
      eventOn(tavern_events.CHAT_CREATED, () => {
        log('CHAT_CREATED');
        scheduleApply();
      });
      eventOn(tavern_events.CHARACTER_PAGE_LOADED, () => {
        log('CHARACTER_PAGE_LOADED');
        scheduleApply();
      });

      eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, () => {
        log('VARIABLE_UPDATE_ENDED');
        scheduleApply();
      });

      const BTN = '📘 AC6 同步世界书';
      if (typeof appendInexistentScriptButtons === 'function') {
        appendInexistentScriptButtons([{ name: BTN, visible: true }]);
        eventOn(getButtonEvent(BTN), () => {
          errorCatched(applyWorldbook)();
        });
      }
    })();
