      }

      .loadout-slot {
        position: relative;
        margin-bottom: 0.45rem;
        padding: 0.55rem 0.75rem;
        background: rgba(0, 0, 0, 0.42);
        border: 1px solid rgba(114, 130, 131, 0.45);
        cursor: default;
        transition:
          border-color 0.22s ease,
          box-shadow 0.22s ease,
