        border: 1px solid rgba(114, 130, 131, 0.4);
        transition:
          border-color 0.2s ease,
          background 0.2s ease,
          transform 0.2s ease;
      }

      @media (prefers-reduced-motion: no-preference) {
        .inv-card:hover {
          border-color: rgba(216, 232, 233, 0.5);
          background: rgba(216, 232, 233, 0.06);
          transform: translateY(-2px);
        }
      }

      .inv-card__badge {
        display: inline-block;
        margin-bottom: 0.35rem;
        padding: 0.12rem 0.4rem;
        font-size: 0.52rem;
        font-weight: 700;
        letter-spacing: 0.14em;
        color: var(--ac-dark);
        background: linear-gradient(90deg, rgba(216, 232, 233, 0.95), rgba(180, 210, 212, 0.85));
        clip-path: polygon(0 0, calc(100% - 6px) 0, 100% 6px, 100% 100%, 6px 100%, 0 calc(100% - 6px));
      }

      .inv-card__title {
        font-family: var(--font-cn);
        font-size: 0.82rem;
        font-weight: 600;
        color: var(--ac-light);
        line-height: 1.2;
        word-break: break-word;
      }

      .inv-card__meta {
        margin-top: 0.35rem;
        font-size: 0.62rem;
        letter-spacing: 0.04em;
