      }

      .inv-card__desc {
        margin-top: 0.35rem;
        font-size: 0.62rem;
        line-height: 1.4;
        color: rgba(216, 232, 233, 0.72);
        display: -webkit-box;
        -webkit-line-clamp: 3;
        line-clamp: 3;
        -webkit-box-orient: vertical;
        overflow: hidden;
      }

      .inventory-empty {
        padding: 2rem 1rem;
        text-align: center;
        font-size: 0.78rem;
        color: var(--ac-base);
        letter-spacing: 0.08em;
      }

      .garage-panel.mech-stats-panel {
        background: linear-gradient(
          160deg,
          rgba(10, 14, 16, 0.82) 0%,
          rgba(16, 22, 24, 0.68) 45%,
          rgba(12, 18, 20, 0.8) 100%
        );
        border-left: 3px solid rgba(216, 232, 233, 0.45);
      }

      .mech-stat-group {
        margin-bottom: 1rem;
      }

      .mech-stat-group:last-child {
        margin-bottom: 0;
      }

      .mech-stat-group__label {
        font-size: 0.65rem;
        letter-spacing: 0.24em;
        color: var(--ac-base);
        margin-bottom: 0.45rem;
      }

      .mech-stat-line {
        display: flex;
        justify-content: space-between;
        align-items: baseline;
        gap: 0.75rem;
        margin-bottom: 0.4rem;
        font-size: 0.82rem;
        font-family: var(--font-cn);
      }

      .mech-stat-line span:first-child {
        color: rgba(216, 232, 233, 0.65);
        flex-shrink: 0;
      }

      .mech-stat-line span:last-child {
