        font-weight: 600;
        text-align: right;
        font-variant-numeric: tabular-nums;
      }

      /* --- 视图3: 通讯频道 · 立绘交互 --- */
      #view-comms {
        flex-direction: column;
        gap: 0;
        height: 100%;
        max-height: 100%;
        min-height: 0;
        min-width: 0;
        overflow: hidden;
        padding-bottom: 0.75rem;
        box-sizing: border-box;
      }

      /* 频道视图头部 */
      .comms-head {
        flex-shrink: 0;
        display: flex;
        align-items: center;
        justify-content: space-between;
        padding: 0 0 0.6rem 0;
        border-bottom: 1px solid rgba(114, 130, 131, 0.35);
        margin-bottom: 0.75rem;
      }
      .comms-head__title {
        font-family: var(--font-cn);
        font-size: 0.72rem;
        font-weight: 600;
        letter-spacing: 0.28em;
        color: rgba(216, 232, 233, 0.92);
      }
      .comms-head__sub {
        font-size: 0.62rem;
        letter-spacing: 0.16em;
        color: var(--ac-base);
      }

      /* 立绘横向滚动容器（overflow-x: auto；立绘宽度不再按「7 列均分」，超出时出现滚动条） */
      .comms-strip {
        flex: 1;
        display: flex;
        flex-direction: row;
        flex-wrap: nowrap;
        gap: 0.65rem;
        /* 关键：列向 flex 子项默认 min-width:auto 会按子内容撑宽，内部永不 overflow，滚动条不会出现 */
        min-width: 0;
        width: 100%;
        max-width: 100%;
        overflow-x: auto;
        overflow-y: hidden;
        padding-bottom: 0.65rem;
        align-items: center;
        min-height: 0;
        position: relative;
        container-type: size;
        container-name: comms-strip;
        scrollbar-width: thin;
        scrollbar-color: rgba(216, 232, 233, 0.28) rgba(0, 0, 0, 0.25);
        scroll-behavior: smooth;
        overscroll-behavior-x: contain;
      }
      .comms-strip::-webkit-scrollbar {
        height: 5px;
      }
      .comms-strip::-webkit-scrollbar-track {
        background: rgba(0, 0, 0, 0.25);
        border-radius: 3px;
      }
      .comms-strip::-webkit-scrollbar-thumb {
        background: rgba(216, 232, 233, 0.3);
        border-radius: 3px;
      }

      /* 每个立绘槽位 — 832:1216（13:19）；理想宽度由 clamp 决定，高度由条带 cqh 封顶，超出条带宽度则横向滚动 */
      .portrait-slot {
        flex: 0 0 auto;
        position: relative;
        display: flex;
        flex-direction: column;
        cursor: pointer;
        box-sizing: border-box;
        align-self: center;
        width: clamp(132px, 17vw, 360px);
        min-width: 0;
        max-height: 100%;
        aspect-ratio: 832 / 1216;
        transition:
          transform 0.25s cubic-bezier(0.34, 1.56, 0.64, 1),
          filter 0.2s ease;
      }
      @container comms-strip (min-width: 0) {
        .portrait-slot {
          width: min(clamp(198px, 24vw, 540px), calc(100cqh * 832 / 1216));
        }
      }
      .portrait-slot:hover {
        transform: translateY(-4px) scale(1.02);
        filter: brightness(1.08);
      }
      .portrait-slot.expanded {
        transform: translateY(-6px) scale(1.04);
        filter: brightness(1.12) saturate(1.1);
      }

      /* 切角面板容器 */
      .portrait-inner {
        position: relative;
        flex: 1;
        height: 100%;
        min-height: 0;
        overflow: hidden;
        background: linear-gradient(160deg, rgba(10, 14, 16, 0.88) 0%, rgba(16, 22, 24, 0.72) 100%);
        border: 1px solid rgba(216, 232, 233, 0.2);
        box-shadow:
          0 0 0 1px rgba(114, 130, 131, 0.1) inset,
          0 12px 32px rgba(0, 0, 0, 0.45),
          0 0 24px rgba(114, 130, 131, 0.06);
        backdrop-filter: blur(8px);
        display: flex;
        flex-direction: column;
        transition:
          border-color 0.25s ease,
          box-shadow 0.25s ease;
        clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 12px 100%, 0 calc(100% - 12px));
      }
      .portrait-slot.expanded .portrait-inner {
        border-color: rgba(216, 232, 233, 0.5);
        box-shadow:
          0 0 0 1px rgba(216, 232, 233, 0.15) inset,
          0 16px 40px rgba(0, 0, 0, 0.55),
          0 0 40px rgba(114, 130, 131, 0.15);
      }

      /* 扫描线纹理叠加 */
      .portrait-inner::before {
        content: '';
        position: absolute;
        inset: 0;
        background: repeating-linear-gradient(
          0deg,
          transparent,
          transparent 3px,
          rgba(216, 232, 233, 0.025) 3px,
          rgba(216, 232, 233, 0.025) 4px
        );
        pointer-events: none;
        z-index: 2;
      }

      /* 悬停光晕边角 */
      .portrait-corner-tl,
      .portrait-corner-tr,
      .portrait-corner-bl,
      .portrait-corner-br {
        position: absolute;
        width: 12px;
        height: 12px;
        border: 1.5px solid rgba(216, 232, 233, 0.25);
        pointer-events: none;
        z-index: 3;
        transition:
          border-color 0.25s ease,
          opacity 0.25s ease;
      }
      .portrait-corner-tl {
        top: 6px;
        left: 6px;
        border-right: none;
        border-bottom: none;
      }
      .portrait-corner-tr {
        top: 6px;
        right: 6px;
        border-left: none;
        border-bottom: none;
      }
      .portrait-corner-bl {
        bottom: 6px;
        left: 6px;
        border-right: none;
        border-top: none;
      }
      .portrait-corner-br {
        bottom: 6px;
        right: 6px;
        border-left: none;
        border-top: none;
      }
      .portrait-slot:hover .portrait-corner-tl,
      .portrait-slot.expanded .portrait-corner-tl {
        border-color: rgba(216, 232, 233, 0.55);
      }
      .portrait-slot.expanded .portrait-corner-tl,
      .portrait-slot.expanded .portrait-corner-tr,
      .portrait-slot.expanded .portrait-corner-bl,
      .portrait-slot.expanded .portrait-corner-br {
        border-color: rgba(216, 232, 233, 0.7);
        box-shadow: 0 0 8px rgba(216, 232, 233, 0.25);
      }

      /* 立绘图片区 */
      .portrait-img-wrap {
        flex: 1;
        position: relative;
        overflow: hidden;
        min-height: 0;
      }
      .portrait-img {
        width: 100%;
        height: 100%;
        object-fit: cover;
        object-position: center top;
        display: block;
        transition:
          transform 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94),
          opacity 0.3s ease;
      }
      .portrait-slot:hover .portrait-img {
        transform: scale(1.04);
      }
      .portrait-slot.expanded .portrait-img {
        transform: scale(1.06);
      }

      /* 悬停蒙层 */
      .portrait-hover-overlay {
        position: absolute;
        inset: 0;
        background: linear-gradient(to bottom, rgba(0, 0, 0, 0) 40%, rgba(0, 0, 0, 0.55) 100%);
        opacity: 0;
        transition: opacity 0.25s ease;
        z-index: 1;
        pointer-events: none;
      }
      .portrait-slot:hover .portrait-hover-overlay {
        opacity: 1;
      }

      /* 展开时的渐变 — 让底部不那么突兀 */
      .portrait-slot.expanded .portrait-hover-overlay {
        background: linear-gradient(to bottom, rgba(0, 0, 0, 0) 0%, rgba(0, 0, 0, 0.3) 50%, rgba(0, 0, 0, 0.7) 100%);
        opacity: 1;
      }

      /* 底部名称 + 信息区（absolute 定位在底部） */
      .portrait-footer {
        position: relative;
        z-index: 2;
        padding: 0.5rem 0.4rem 0.5rem;
        background: linear-gradient(to top, rgba(0, 0, 0, 0.75) 0%, transparent 100%);
        display: flex;
        flex-direction: column;
        gap: 0.3rem;
      }

      /* 角色名称 */
      .portrait-name {
        font-family: var(--font-cn);
        font-size: 0.72rem;
        font-weight: 700;
        letter-spacing: 0.12em;
        color: var(--ac-light);
        text-align: center;
        text-shadow:
          0 0 12px rgba(216, 232, 233, 0.4),
          0 1px 3px rgba(0, 0, 0, 0.8);
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
        transition:
          transform 0.35s cubic-bezier(0.25, 0.46, 0.45, 0.94),
          opacity 0.3s ease,
          font-size 0.25s ease;
        transform-origin: center center;
        line-height: 1.2;
        margin: 0;
      }

      /* 展开状态：名称左滑缩小 */
      .portrait-slot.expanded .portrait-name {
        transform: translateX(-8px) scale(0.82);
        opacity: 0.7;
        text-align: right;
        margin-right: 2px;
      }

      /* 好感度 / 默契度进度条区域 */
      .portrait-info {
        display: flex;
        flex-direction: column;
        gap: 0.28rem;
        overflow: hidden;
        max-height: 0;
        opacity: 0;
        transition:
          max-height 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94),
          opacity 0.35s ease,
          margin-top 0.1s;
        margin-top: 0;
      }
      .portrait-slot.expanded .portrait-info {
        max-height: 60px;
        opacity: 1;
        margin-top: 0.15rem;
      }

      /* 单条进度条 */
      .portrait-bar-row {
        display: flex;
        align-items: center;
        gap: 0.35rem;
      }
      .portrait-bar-icon {
        flex-shrink: 0;
        width: 12px;
        height: 12px;
        display: flex;
        align-items: center;
        justify-content: center;
        color: var(--ac-base);
      }
      .portrait-bar-label {
        flex-shrink: 0;
        font-family: var(--font-cn);
        font-size: 0.52rem;
        font-weight: 600;
        letter-spacing: 0.1em;
        color: rgba(216, 232, 233, 0.65);
        width: 28px;
        text-align: right;
      }
      .portrait-bar-track {
        flex: 1;
        position: relative;
        height: 5px;
        background: rgba(0, 0, 0, 0.5);
        border: 1px solid rgba(114, 130, 131, 0.3);
        border-radius: 3px;
        overflow: hidden;
        box-shadow: inset 0 1px 3px rgba(0, 0, 0, 0.5);
      }
      .portrait-bar-fill {
        position: absolute;
        top: 0;
        left: 0;
        height: 100%;
        width: 0%;
        border-radius: 2px;
        transition: width 0.55s cubic-bezier(0.25, 0.8, 0.25, 1);
        transform-origin: left center;
      }
      .portrait-bar-fill--favor {
        background: linear-gradient(90deg, hsl(0, 72%, 52%), hsl(358, 80%, 62%));
        box-shadow: 0 0 8px hsla(358, 80%, 60%, 0.5);
      }
      .portrait-bar-fill--rapport {
        background: linear-gradient(90deg, hsl(330, 70%, 60%), hsl(345, 80%, 68%));
        box-shadow: 0 0 8px hsla(345, 80%, 65%, 0.5);
      }
      /* 进度条光效 */
      .portrait-bar-fill::after {
        content: '';
        position: absolute;
        inset: 0;
        background: linear-gradient(90deg, transparent 0%, rgba(255, 255, 255, 0.25) 50%, transparent 100%);
        animation: bar-shimmer 2.5s ease-in-out infinite;
      }
      @keyframes bar-shimmer {
        0% {
          transform: translateX(-100%);
          opacity: 0.6;
        }
        50% {
          transform: translateX(100%);
          opacity: 0.3;
        }
        100% {
          transform: translateX(200%);
          opacity: 0;
        }
      }

      .portrait-bar-value {
        flex-shrink: 0;
        font-family: var(--font-main);
        font-size: 0.58rem;
        font-weight: 600;
        color: var(--ac-light);
        width: 22px;
        text-align: left;
        letter-spacing: 0.03em;
      }

      /* 切换按钮（位于立绘右上角） */
      .portrait-cycle-btn {
        position: absolute;
        top: 8px;
        right: 8px;
        z-index: 4;
        width: 20px;
        height: 20px;
        display: flex;
        align-items: center;
        justify-content: center;
        background: rgba(0, 0, 0, 0.55);
        border: 1px solid rgba(216, 232, 233, 0.3);
        border-radius: 3px;
        color: rgba(216, 232, 233, 0.7);
        cursor: pointer;
        opacity: 0;
        transition:
          opacity 0.2s ease,
          background 0.2s ease,
          color 0.2s ease;
        backdrop-filter: blur(4px);
      }
      .portrait-slot:hover .portrait-cycle-btn {
        opacity: 1;
      }
      .portrait-cycle-btn:hover {
        background: rgba(216, 232, 233, 0.15);
        border-color: rgba(216, 232, 233, 0.6);
        color: var(--ac-light);
      }

      /* 关系阶段角标 */
      .portrait-phase-chip {
        position: absolute;
        top: 8px;
        left: 8px;
        z-index: 4;
        padding: 0.12rem 0.4rem;
        font-family: var(--font-cn);
        font-size: 0.48rem;
        font-weight: 700;
        letter-spacing: 0.1em;
        color: rgba(0, 0, 0, 0.8);
        background: linear-gradient(135deg, rgba(216, 232, 233, 0.95), rgba(160, 200, 202, 0.85));
        clip-path: polygon(0 0, calc(100% - 4px) 0, 100% 4px, 100% 100%, 4px 100%, 0 calc(100% - 4px));
        box-shadow: 0 0 8px rgba(216, 232, 233, 0.3);
        white-space: nowrap;
        max-width: calc(100% - 40px);
        overflow: hidden;
        text-overflow: ellipsis;
      }

      /* 空数据占位 */
      .comms-empty {
        flex: 1;
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        gap: 0.75rem;
        padding: 3rem 1rem;
        color: var(--ac-base);
        text-align: center;
      }
      .comms-empty__icon {
        opacity: 0.4;
        animation: comms-pulse 3s ease-in-out infinite;
      }
      @keyframes comms-pulse {
        0%,
        100% {
          opacity: 0.3;
          transform: scale(1);
        }
        50% {
          opacity: 0.55;
          transform: scale(1.05);
        }
      }
      .comms-empty__text {
        font-family: var(--font-cn);
        font-size: 0.78rem;
        letter-spacing: 0.2em;
        opacity: 0.6;
      }

      /* ================= 通讯频道原有样式（仅保留给 nav-btn 提示用） ================= */

      /* --- 视图4: 作战与行动 --- */
      #view-missions {
        flex-direction: column;
        gap: 15px;
        max-width: 600px;
      }
      .mission-card {
        background: rgba(0, 0, 0, 0.6);
        border: 1px solid var(--ac-base);
        padding: 20px;
        display: flex;
        justify-content: space-between;
        align-items: center;
      }
      .mission-title {
        font-size: 18px;
        font-weight: 600;
        color: var(--ac-light);
      }
      .mission-type {
        font-size: 12px;
        color: var(--ac-base);
        padding: 2px 6px;
        border: 1px solid var(--ac-base);
        margin-left: 10px;
      }
      .mission-status {
        font-size: 14px;
        letter-spacing: 2px;
      }

      /* ================= 底部控制栏 ================= */
      #ac-bottom-bar {
        position: absolute;
        bottom: 20px;
        left: 40px;
        right: 40px;
        display: flex;
        justify-content: space-between;
        align-items: center;
        border-top: 1px solid rgba(114, 130, 131, 0.3);
        padding-top: 10px;
      }
      .key-hints {
        display: flex;
        gap: 20px;
        font-size: 12px;
        color: var(--ac-base);
      }
      .key-btn {
        border: 1px solid var(--ac-base);
        padding: 2px 6px;
        border-radius: 2px;
        color: var(--ac-light);
        margin-right: 5px;
      }

      .upload-btn {
        background: transparent;
        border: 1px solid var(--ac-base);
        color: var(--ac-light);
        padding: 5px 15px;
        font-family: var(--font-main);
        cursor: pointer;
        font-size: 12px;
        transition: 0.2s;
        display: flex;
        align-items: center;
        gap: 5px;
      }
      .upload-btn:hover {
        background: var(--ac-light);
        color: var(--ac-dark);
      }

      /* ================= 动画 ================= */
      @keyframes glitch-in {
        0% {
          opacity: 0;
          transform: translateX(-10px) skewX(10deg);
          filter: drop-shadow(2px 0 0 red) drop-shadow(-2px 0 0 cyan);
        }
        50% {
          opacity: 0.8;
          transform: translateX(5px) skewX(-5deg);
          filter: none;
        }
        100% {
          opacity: 1;
          transform: translateX(0) skewX(0);
        }
      }

      /* ================= 子界面收起/展开动画 ================= */
      @keyframes slide-in {
        from {
          opacity: 0;
          transform: translateX(30px);
        }
        to {
          opacity: 1;
          transform: translateX(0);
        }
      }

      @keyframes slide-out {
        from {
          opacity: 1;
          transform: translateX(0);
        }
        to {
          opacity: 0;
          transform: translateX(30px);
        }
      }

      .ac-view.collapsing {
        animation: slide-out 0.25s cubic-bezier(0.25, 0.46, 0.45, 0.94) both;
      }

      .ac-view.expanding {
        animation: slide-in 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94) both;
      }

      /* 收起按钮样式 */
      .collapse-btn {
        position: absolute;
        top: 10px;
        right: 10px;
        width: 28px;
        height: 28px;
        background: rgba(0, 0, 0, 0.6);
        border: 1px solid var(--ac-border);
        color: var(--ac-base);
        cursor: pointer;
        display: flex;
        align-items: center;
        justify-content: center;
        transition: all 0.2s ease;
        z-index: 10;
        clip-path: polygon(0 0, calc(100% - 6px) 0, 100% 6px, 100% 100%, 6px 100%, 0 calc(100% - 6px));
      }

      .collapse-btn:hover {
        background: rgba(216, 232, 233, 0.15);
        border-color: var(--ac-light);
        color: var(--ac-light);
      }

      .collapse-btn i {
        transition: transform 0.3s ease;
      }

      .collapse-btn:hover i {
        transform: scale(1.1);
      }

      /* ================= 移动端适配 @media (max-width: 768px) ================= */
      @media (max-width: 768px) {
        /* 1. 整体容器：取消强制 16:9，改为内容自适应 */
        #ac6-outer {
          aspect-ratio: auto;
          min-height: 100svh;
          height: auto;
          min-height: 600px;
        }

        /* 2. #ac6-system 改为竖向文档流 */
        #ac6-system {
          position: relative;
          height: auto;
          min-height: 100svh;
          flex-direction: column;
          overflow-y: auto;
          overflow-x: hidden;
        }

        /* 3. 左侧导航 → 底部固定横向导航栏 */
        #ac-sidebar {
          position: fixed;
          bottom: 0;
          left: 0;
          right: 0;
          top: auto;
          width: 100%;
          height: auto;
          padding: 0;
          flex-direction: row;
          background: linear-gradient(0deg, rgba(0, 0, 0, 0.85) 0%, rgba(0, 0, 0, 0.6) 80%, transparent 100%);
          z-index: 100;
          order: 10;
          border-top: 1px solid rgba(216, 232, 233, 0.18);
          backdrop-filter: blur(12px);
          -webkit-backdrop-filter: blur(12px);
          overflow-x: auto;
          overflow-y: hidden;
          scrollbar-width: none;
          -webkit-overflow-scrolling: touch;
        }

        #ac-sidebar::-webkit-scrollbar {
          display: none;
        }

        .ac-header {
          display: none;
        }

        .nav-btn {
          flex-direction: column;
          justify-content: center;
          align-items: center;
          width: auto;
          min-width: 64px;
          flex: 1;
          padding: 8px 4px;
          margin-bottom: 0;
          font-size: 9px;
          letter-spacing: 0.5px;
          gap: 4px;
          border-left: 1px solid rgba(114, 130, 131, 0.12);
          text-align: center;
        }

        .nav-btn i {
          font-size: 18px !important;
          width: 20px;
          height: 20px;
        }

        .nav-btn::before {
          width: 100%;
          height: 2px;
          top: auto;
          bottom: 0;
          left: 0;
          right: 0;
          opacity: 0;
        }

        .nav-btn.active {
          background: rgba(216, 232, 233, 0.12);
          border-top: 2px solid var(--ac-light);
        }

        .nav-btn.active::before {
          opacity: 1;
          background: var(--ac-light);
        }

        .nav-btn .expand-hint {
          display: none;
        }

        /* 收起按钮悬浮提示（底部导航模式下调整位置） */
        .collapse-hint {
          bottom: 70px;
          top: auto;
        }

        /* 4. 右上角资源区：改为顶部横条 */
        #ac-topbar {
          position: relative;
          top: 0;
          right: 0;
          display: flex;
          flex-direction: row;
          justify-content: flex-end;
          align-items: center;
          gap: 12px;
          padding: 8px 12px;
          border-bottom: 1px solid rgba(114, 130, 131, 0.2);
          background: rgba(0, 0, 0, 0.4);
          backdrop-filter: blur(8px);
          -webkit-backdrop-filter: blur(8px);
          order: 1;
        }

        .resource-item {
          margin-bottom: 0;
          gap: 6px;
        }

        .res-label {
          font-size: 10px;
          letter-spacing: 1px;
        }

        .res-value {
          font-size: 15px;
        }

        /* 5. 主内容区：减小边距 */
        #ac-content-area {
          padding: 12px;
          order: 2;
          flex: 1;
          min-height: 0;
        }

        .ac-view {
          top: 12px;
          left: 12px;
          right: 12px;
          bottom: 72px; /* 底部导航高度 */
          padding: 0;
        }

        /* 6. 状态总览视图 */
        #view-status {
          max-width: 100%;
          overflow-y: auto;
          -webkit-overflow-scrolling: touch;
          overscroll-behavior: contain;
          scrollbar-width: thin;
          scrollbar-color: rgba(114, 130, 131, 0.4) transparent;
        }

        #view-status::-webkit-scrollbar {
          width: 4px;
        }

        #view-status::-webkit-scrollbar-track {
          background: transparent;
        }

        #view-status::-webkit-scrollbar-thumb {
          background: rgba(114, 130, 131, 0.4);
          border-radius: 2px;
        }

        .status-hud-panel {
          padding: clamp(1rem, 4vw, 1.5rem);
          overflow: visible;
        }

        .status-section__head {
          flex-wrap: wrap;
          gap: 0.5rem;
        }

        .status-metric__label {
          font-size: 0.75rem;
        }

        .status-metric__value {
          font-size: 0.9rem;
        }

        .status-metric__icon {
          width: 30px;
          height: 30px;
        }

        /* 7. AC整备视图 */
        .garage-layout {
          flex-direction: column;
          gap: 0.6rem;
        }

        .garage-col--loadout,
        .garage-col--inventory,
        .garage-col--stats {
          flex: 0 0 auto;
          width: 100%;
        }

        .inventory-grid {
          grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
          gap: 0.4rem;
        }

        .garage-page-head {
          flex-direction: column;
          align-items: flex-start;
          gap: 0.5rem;
        }

        .garage-panel {
          padding: 0.75rem;
        }

        .mech-stats-panel {
          border-left: none;
          border-top: 3px solid rgba(216, 232, 233, 0.45);
        }

        /* 8. 通讯频道视图 */
        #view-comms {
          padding-bottom: 0;
          height: calc(100% - 72px);
        }

        .comms-strip {
          gap: 0.5rem;
          padding-bottom: 0.5rem;
          overflow-x: scroll;
          -webkit-overflow-scrolling: touch;
          touch-action: pan-x;
        }

        .portrait-slot {
          width: clamp(110px, 35vw, 180px);
          flex-shrink: 0;
        }

        @container comms-strip (min-width: 0) {
          .portrait-slot {
            width: min(clamp(110px, 35vw, 180px), calc(100cqh * 832 / 1216));
          }
        }

        .portrait-name {
          font-size: 0.65rem;
        }

        .portrait-bar-label {
          width: 22px;
          font-size: 0.48rem;
        }

        .portrait-bar-value {
          font-size: 0.52rem;
          width: 18px;
        }

        /* 9. 作战与行动视图 */
        #view-missions {
          max-width: 100%;
          gap: 10px;
        }

        .mission-card {
          flex-direction: column;
          align-items: flex-start;
          gap: 8px;
          padding: 14px;
        }

        .mission-title {
          font-size: 15px;
        }

        /* 10. 底部控制栏 */
        #ac-bottom-bar {
          display: none;
        }

        /* 11. 收起按钮位置微调 */
        .collapse-btn {
          top: 6px;
          right: 6px;
          width: 24px;
          height: 24px;
        }

        /* 12. HUD 干扰纹理：移动端降低密度，提升可读性 */
        #ac-hud-overlay {
          opacity: 0.3;
        }

        /* 13. 遮罩层移动端适配 */
        #ac-overlay.active {
          background: rgba(0, 0, 0, 0.3);
        }

        /* 14. 扫描线纹理移动端减轻 */
        .status-hud-panel::before,
        .garage-panel::before,
        .portrait-inner::before {
          opacity: 0.4;
        }

        /* 15. 确保触摸友好：所有可交互元素最小触摸目标 44px */
        .nav-btn,
        .collapse-btn,
        .inv-card,
        .portrait-slot,
        .upload-btn,
        .portrait-cycle-btn {
          min-height: 44px;
          min-width: 44px;
        }

        .nav-btn {
          min-height: 56px;
        }

        /* 16. 立绘切换按钮移动端更易触摸 */
        .portrait-cycle-btn {
          width: 24px;
          height: 24px;
          top: 6px;
          right: 6px;
          opacity: 0.7;
        }

        /* 17. 关系阶段角标移动端优化 */
        .portrait-phase-chip {
          font-size: 0.42rem;
          padding: 0.1rem 0.3rem;
        }
      }

      /* 超窄屏额外处理 (< 400px) */
      @media (max-width: 400px) {
        #ac-sidebar .nav-btn {
          min-width: 56px;
          padding: 6px 2px;
          font-size: 8px;
        }

        .nav-btn i {
          font-size: 16px !important;
        }

        .inventory-grid {
          grid-template-columns: repeat(auto-fill, minmax(110px, 1fr));
        }

        .portrait-slot {
          width: clamp(95px, 40vw, 140px);
        }
      }
    </style>
  </head>
  <body>
    <div id="ac6-outer">
      <div id="ac6-system">
        <!-- 背景层 -->
        <div id="ac-bg-layer"></div>
        <div id="ac-vignette"></div>
        <div id="ac-hud-overlay"></div>
        <!-- 遮罩层 -->
        <div id="ac-overlay"></div>

        <!-- 左侧导航 -->
        <div id="ac-sidebar" class="interactive-layer">
          <div class="ac-header"><i data-lucide="hexagon"></i> SYSTEM_OS</div>
          <button class="nav-btn active" data-target="view-status"><i data-lucide="activity"></i> 状态总览</button>
          <button class="nav-btn" data-target="view-garage"><i data-lucide="wrench"></i> AC 整备</button>
          <button class="nav-btn" data-target="view-comms"><i data-lucide="radio"></i> 通讯频道</button>
          <button class="nav-btn" data-target="view-missions"><i data-lucide="crosshair"></i> 作战与行动</button>
        </div>

        <!-- 右上角资源 -->
        <div id="ac-topbar">
          <div class="resource-item">
            <i data-lucide="coins" size="16" color="var(--ac-base)"></i>
            <span class="res-label">COAM</span>
            <span class="res-value" id="ui-cage">0</span>
          </div>
          <div class="resource-item">
            <i data-lucide="cpu" size="16" color="var(--ac-base)"></i>
            <span class="res-label">KRL LVL</span>
            <span class="res-value" id="ui-krl">1</span>
          </div>
        </div>

        <!-- 主内容区 -->
        <div id="ac-content-area" class="interactive-layer">
          <!-- 1. 状态总览 -->
          <div id="view-status" class="ac-view" aria-labelledby="status-page-title">
            <button class="collapse-btn" onclick="collapseView('view-status')" title="收起界面">
              <i data-lucide="x" size="16"></i>
              <span class="collapse-hint">点击收起 / 再次点击导航按钮</span>
            </button>
            <h1 id="status-page-title" class="sr-only">状态总览</h1>
            <div class="status-hud-panel panel-chamfer">
              <span class="hud-frame-corner hud-frame-corner--tl" aria-hidden="true"></span>
              <span class="hud-frame-corner hud-frame-corner--tr" aria-hidden="true"></span>
              <span class="hud-frame-corner hud-frame-corner--bl" aria-hidden="true"></span>
              <span class="hud-frame-corner hud-frame-corner--br" aria-hidden="true"></span>

              <section class="status-section" aria-labelledby="status-pilot-heading">
                <div class="status-section__head">
                  <div>
                    <h2 id="status-pilot-heading" class="status-section__title">PILOT STATUS</h2>
                    <span class="status-section__sub">驾驶员战术读数</span>
                  </div>
                  <div class="status-rank-chip" id="status-rank-chip" title="驾驶员评级">
                    <span id="ui-pilot-rank">民兵</span>
                  </div>
                </div>

                <div class="status-metric">
                  <div class="status-metric__icon" aria-hidden="true"><i data-lucide="heart-pulse" size="18"></i></div>
                  <div class="status-metric__body">
                    <div class="status-metric__row">
                      <span class="status-metric__label">AP（机体耐损）</span>
                      <span class="status-metric__value"><span id="ui-hp">100</span> / 100</span>
                    </div>
                    <div
                      class="hud-bar-track"
                      role="progressbar"
                      aria-valuemin="0"
                      aria-valuemax="100"
                      aria-valuenow="100"
                      id="bar-hp-track"
                    >
                      <div class="hud-bar-fill hud-bar-fill--hp" id="bar-hp" style="width: 100%"></div>
                    </div>
                  </div>
                </div>

                <div class="status-metric">
                  <div class="status-metric__icon" aria-hidden="true"><i data-lucide="brain" size="18"></i></div>
                  <div class="status-metric__body">
                    <div class="status-metric__row">
                      <span class="status-metric__label">SP（精神力）</span>
                      <span class="status-metric__value"><span id="ui-sp">100</span> / 100</span>
                    </div>
                    <div
                      class="hud-bar-track"
                      role="progressbar"
                      aria-valuemin="0"
                      aria-valuemax="100"
                      aria-valuenow="100"
                      id="bar-sp-track"
                    >
                      <div class="hud-bar-fill hud-bar-fill--sp" id="bar-sp" style="width: 100%"></div>
                    </div>
                  </div>
                </div>

                <div class="status-metric">
                  <div class="status-metric__icon" aria-hidden="true"><i data-lucide="shield" size="18"></i></div>
                  <div class="status-metric__body">
                    <div class="status-metric__row">
                      <span class="status-metric__label">珂若尔护盾</span>
                      <span class="status-metric__value"
                        ><span id="ui-shield-cur">10</span> / <span id="ui-shield-max">10</span></span
                      >
                    </div>
                    <div
                      class="hud-bar-track"
                      role="progressbar"
                      aria-valuemin="0"
                      aria-valuemax="10"
                      aria-valuenow="10"
                      id="bar-shield-track"
                    >
                      <div class="hud-bar-fill hud-bar-fill--shield" id="bar-shield" style="width: 100%"></div>
                    </div>
                  </div>
                </div>

                <div class="status-metric status-metric--compact">
                  <div class="status-metric__icon" aria-hidden="true"><i data-lucide="gauge" size="18"></i></div>
                  <div class="status-metric__body">
                    <div class="status-metric__row">
                      <span class="status-metric__label">APM（操作力）</span>
                      <span class="status-metric__value" id="ui-apm">0</span>
                    </div>
                  </div>
                </div>

                <div class="status-metric">
                  <div class="status-metric__icon" aria-hidden="true"><i data-lucide="activity" size="18"></i></div>
                  <div class="status-metric__body">
                    <div class="status-metric__row">
                      <span class="status-metric__label">神经同步率</span>
                      <span class="status-metric__value" id="ui-sync">0 / 60%</span>
                    </div>
                    <div
                      class="hud-bar-track"
                      role="progressbar"
                      aria-valuemin="0"
                      aria-valuemax="60"
                      aria-valuenow="0"
                      id="bar-sync-track"
                    >
                      <div class="hud-bar-fill hud-bar-fill--sync" id="bar-sync" style="width: 0%"></div>
                    </div>
                  </div>
                </div>

              </section>

              <section class="status-section" aria-labelledby="status-system-heading">
                <div class="status-section__head">
                  <div>
                    <h2 id="status-system-heading" class="status-section__title">SYSTEM SYNC</h2>
                    <span class="status-section__sub">交感伺服链路</span>
                  </div>
                </div>

                <div class="status-metric status-metric--compact">
                  <div class="status-metric__icon" aria-hidden="true"><i data-lucide="link-2" size="18"></i></div>
                  <div class="status-metric__body">
                    <div class="status-metric__row">
                      <span class="status-metric__label">交感伺服状态</span>
                      <span class="status-metric__value status-metric__value--dim" id="ui-sync-status">离线</span>
                    </div>
