                margin-bottom: 10px;
                border-bottom: 1px solid var(--ac-base);
                padding-bottom: 5px;
              "
            >
              SORTIE / MISSIONS
            </div>
            <div id="ui-mission-list" style="display: flex; flex-direction: column; gap: 10px">
              <!-- 动态生成 -->
            </div>
          </div>
        </div>

        <!-- 底部控制栏 -->
        <div id="ac-bottom-bar" class="interactive-layer">
          <div></div>
          <div>
            <input type="file" id="bg-upload" accept="image/*" style="display: none" />
            <button class="upload-btn" onclick="document.getElementById('bg-upload').click()">
              <i data-lucide="image" size="14"></i> 自定义背景
            </button>
          </div>
        </div>
      </div>
    </div>
    <!-- /#ac6-outer -->

    <script>
      // 初始化图标
      lucide.createIcons();

      // ================= 子界面展开/收起状态管理 =================
      let currentActiveView = null; // 当前展开的视图ID，默认无

      // 收起视图函数（供收起按钮调用）
      function collapseView(viewId) {
        const view = document.getElementById(viewId);
        if (!view) return;

        // 添加收起动画
        view.classList.add('collapsing');

        // 动画结束后隐藏
        setTimeout(() => {
          view.classList.remove('active', 'collapsing', 'expanding');
          // 取消导航按钮的 active 状态
          document.querySelectorAll('.nav-btn').forEach(btn => btn.classList.remove('active'));
          currentActiveView = null;
          document.title = 'AC6 战术操作系统';
          lucide.createIcons(); // 重新初始化图标
        }, 250);
      }

      const VIEW_DOCUMENT_TITLES = {
        'view-status': 'AC6 战术操作系统 · 状态总览',
        'view-garage': 'AC6 战术操作系统 · AC 整备',
        'view-comms': 'AC6 战术操作系统 · 通讯频道',
        'view-missions': 'AC6 战术操作系统 · 作战与行动',
      };

      // ================= UI 交互逻辑 =================
      const navBtns = document.querySelectorAll('.nav-btn');
      const views = document.querySelectorAll('.ac-view');

      navBtns.forEach(btn => {
        btn.addEventListener('click', () => {
          const targetId = btn.getAttribute('data-target');
          const targetView = document.getElementById(targetId);

          if (currentActiveView === targetId) {
            // 如果点击的是当前已展开的视图，则收起
            collapseView(targetId);
            document.title = 'AC6 战术操作系统';
          } else {
            // 收起之前的视图
            if (currentActiveView) {
              const prevView = document.getElementById(currentActiveView);
              if (prevView) {
                prevView.classList.remove('active');
              }
            }

            // 移除所有导航按钮的 active
            navBtns.forEach(b => b.classList.remove('active'));

            // 添加当前 active
            btn.classList.add('active');

            // 显示新视图并添加展开动画
            targetView.classList.remove('collapsing');
            targetView.classList.add('active', 'expanding');
            currentActiveView = targetId;
            document.title = VIEW_DOCUMENT_TITLES[targetId] || 'AC6 战术操作系统';

            // 动画结束后移除 expanding 类
            setTimeout(() => {
              targetView.classList.remove('expanding');
              lucide.createIcons(); // 重新初始化图标
            }, 300);
          }
        });
      });

      // 自定义背景上传逻辑
      document.getElementById('bg-upload').addEventListener('change', function (e) {
        const file = e.target.files[0];
        if (file) {
          const reader = new FileReader();
          reader.onload = function (event) {
            document.getElementById('ac-bg-layer').style.backgroundImage = `url(${event.target.result})`;
          };
          reader.readAsDataURL(file);
        }
      });

      // ================= 数据抓取与渲染逻辑 =================

      // 安全获取嵌套对象属性的辅助函数
      const getVal = (obj, path, def = '-') => {
        try {
          return path.split('.').reduce((o, i) => o[i], obj) ?? def;
        } catch (e) {
          return def;
        }
      };

      // 格式化数字加逗号
      const fmtNum = num => Number(num).toLocaleString();

      /** 将 MVU / getVariables 返回的根对象统一为 stat_data 业务层 */
      function normalizeMvuRoot(raw) {
        if (raw == null || typeof raw !== 'object') return null;
        if (raw.stat_data != null && typeof raw.stat_data === 'object' && !Array.isArray(raw.stat_data)) {
          return raw.stat_data;
        }
        if (raw.主角 != null || raw.机库 != null) return raw;
        const cand = raw.data ?? raw.variables ?? raw.payload ?? raw.mvu;
        if (cand != null && typeof cand === 'object') {
          if (cand.stat_data != null && typeof cand.stat_data === 'object' && !Array.isArray(cand.stat_data)) {
            return cand.stat_data;
          }
          if (cand.机库 != null || cand.主角 != null) return cand;
        }
        return raw;
      }

      function escapeHtml(s) {
        if (s == null) return '';
        return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
      }

      /** 解析机甲泊位：优先「当前驾驶机甲」，否则首个泊位；校验名称不匹配 */
      function pickActiveMech(机库) {
        const berths = 机库 && typeof 机库 === 'object' ? 机库.机甲泊位 : null;
        if (!berths || typeof berths !== 'object') {
          return { name: '', mech: null, berthKeys: [], hint: 'no_berths' };
        }
        const keys = Object.keys(berths);
        if (keys.length === 0) {
          return { name: '', mech: null, berthKeys: keys, hint: 'empty_berths' };
        }
        const explicit = String(机库.当前驾驶机甲 ?? '').trim();
        if (explicit && berths[explicit]) {
          return { name: explicit, mech: berths[explicit], berthKeys: keys, hint: null };
        }
        if (explicit && !berths[explicit]) {
          return { name: keys[0], mech: berths[keys[0]], berthKeys: keys, hint: 'name_mismatch', explicit };
        }
        return {
          name: keys[0],
          mech: berths[keys[0]],
          berthKeys: keys,
          hint: keys.length > 1 ? 'implicit_first' : null,
        };
      }

      const PART_TYPE_LABEL = {
        HEAD: '传感头部',
        CORE: '装甲核心',
        EWR: '电子战套件',
        BOOSTER: '推进器',
        GENERATOR: '发电机',
        LEGS: '腿部机组',
      };

      const PART_TYPE_ORDER = ['HEAD', 'CORE', 'EWR', 'BOOSTER', 'GENERATOR', 'LEGS'];

      function formatPartMeta(part) {
        if (!part || typeof part !== 'object') return '';
        const t = part.部件类型;
        const bits = [];
        if (part.制造商) bits.push(`${part.制造商}`);
        if (part.重量 != null && part.重量 !== '') bits.push(`重量 ${part.重量}`);
        if (t === 'CORE') {
          if (part.装甲等级) bits.push(String(part.装甲等级));
          if (part.装甲值 != null) bits.push(`装甲 ${part.装甲值}`);
          if (part.结构值 != null) bits.push(`结构 ${part.结构值}`);
        }
        if (t === 'HEAD' && part.观测效益 != null) bits.push(`观测 ${part.观测效益}`);
        if (t === 'EWR' && part.电子战评级 != null) bits.push(`EWR ${part.电子战评级}`);
        if (t === 'BOOSTER' && part.总出力 != null) bits.push(`出力 ${part.总出力}`);
        if (t === 'GENERATOR' && part.总能源 != null) bits.push(`能源 ${part.总能源}`);
        if (t === 'LEGS' && part.机体类型) bits.push(String(part.机体类型));
        return bits.join(' · ');
      }

      function renderGarageSection(data) {
        const loadoutEl = document.getElementById('garage-loadout-list');
        const invEl = document.getElementById('garage-inventory-grid');
        const invCountEl = document.getElementById('garage-inventory-count');
        const nameEl = document.getElementById('garage-mech-display-name');
        const alertBanner = document.getElementById('garage-alert-banner');
        const alertText = document.getElementById('garage-alert-text');

        const 机库 = data.机库;
        const pick = pickActiveMech(机库);
        const mechData = pick.mech;

        let alertMsg = '';
        if (!机库 || typeof 机库 !== 'object') {
          alertMsg = '未检测到机库节点：请确认 MVU 消息变量已写入「机库」字段。';
        } else if (pick.hint === 'no_berths' || pick.hint === 'empty_berths') {
          alertMsg = '机甲泊位无有效条目：请在变量中配置「机库 · 机甲泊位」。';
        } else if (pick.hint === 'name_mismatch') {
          alertMsg = `「当前驾驶机甲」未匹配泊位（${pick.explicit}），已显示首个泊位机体（${pick.name}）。`;
        } else if (pick.hint === 'implicit_first') {
          alertMsg = '未指定「当前驾驶机甲」，已显示机甲泊位中的第一台机体。';
        }

        if (alertBanner && alertText) {
          if (alertMsg) {
            alertText.textContent = alertMsg;
            alertBanner.classList.add('is-visible');
          } else {
            alertText.textContent = '';
            alertBanner.classList.remove('is-visible');
          }
        }

        if (nameEl) {
          nameEl.textContent = mechData ? pick.name || '—' : '—';
        }

        const slotDefs = [
          { kind: 'weapon', key: '主武器槽', label: '主武装', sub: '右手挂载' },
          { kind: 'weapon', key: '副武器槽', label: '副武装', sub: '左手挂载' },
          { kind: 'frame', key: 'HEAD', label: '头部单元', sub: 'HEAD' },
          { kind: 'frame', key: 'CORE', label: '核心舱段', sub: 'CORE' },
          { kind: 'frame', key: 'EWR', label: '电子战套件', sub: 'EWR' },
          { kind: 'frame', key: 'BOOSTER', label: '推进器', sub: 'BOOSTER' },
          { kind: 'frame', key: 'GENERATOR', label: '发电机', sub: 'GENERATOR' },
          { kind: 'frame', key: 'LEGS', label: '腿部行走机构', sub: 'LEGS' },
        ];

        if (loadoutEl) {
          if (!mechData) {
            loadoutEl.innerHTML =
              '<p class="inventory-empty" style="padding:1rem 0">无装配数据：请先配置机甲泊位与当前机体。</p>';
          } else {
            const build = mechData.构建 || {};
            const weapons = mechData.武器挂载 || {};
            const rows = slotDefs.map(def => {
              let display = '';
              let empty = true;
              if (def.kind === 'weapon') {
                const w = weapons[def.key];
                display = w && w.武器名 ? String(w.武器名) : '';
                empty = !display;
              } else {
                display = build[def.key] != null && build[def.key] !== '' ? String(build[def.key]) : '';
                empty = !display;
              }
              const sub = escapeHtml(def.sub);
              const label = escapeHtml(def.label);
              const nameH = empty ? '未挂载' : escapeHtml(display);
              const cls = empty ? 'loadout-slot loadout-slot--empty panel-chamfer' : 'loadout-slot panel-chamfer';
              return `<div class="${cls}" role="listitem"><div class="loadout-slot__type">${sub} · ${label}</div><div class="loadout-slot__name">${nameH}</div></div>`;
            });
            loadoutEl.innerHTML = `<div role="list">${rows.join('')}</div>`;
          }
        }

        const rawInv = 机库 && typeof 机库 === 'object' ? 机库.可用机甲部件 : null;
        const invEntries = rawInv && typeof rawInv === 'object' && !Array.isArray(rawInv) ? Object.entries(rawInv) : [];

        invEntries.sort((a, b) => {
          const ta = a[1] && a[1].部件类型;
          const tb = b[1] && b[1].部件类型;
          const ia = PART_TYPE_ORDER.indexOf(ta);
          const ib = PART_TYPE_ORDER.indexOf(tb);
          const sa = ia === -1 ? 99 : ia;
          const sb = ib === -1 ? 99 : ib;
          if (sa !== sb) return sa - sb;
          return String(a[0]).localeCompare(String(b[0]), 'zh-Hans-CN');
        });

        if (invCountEl) {
          invCountEl.textContent = `${invEntries.length} 项`;
        }

        if (invEl) {
          if (invEntries.length === 0) {
            invEl.classList.remove('inventory-grid');
            invEl.innerHTML =
              '<div class="inventory-empty">库内无可用部件：请在「机库 · 可用机甲部件」中登记库存。</div>';
          } else {
            invEl.classList.add('inventory-grid');
            invEl.innerHTML = invEntries
              .map(([partName, part]) => {
                const p = part && typeof part === 'object' ? part : {};
                const typeKey = p.部件类型 || '—';
                const badge = PART_TYPE_LABEL[typeKey] || String(typeKey);
                const meta = formatPartMeta(p);
                const desc = p.描述 != null && p.描述 !== '' ? String(p.描述) : '';
                return `<article class="inv-card panel-chamfer" role="listitem" aria-label="${escapeHtml(partName)}">
                  <span class="inv-card__badge">${escapeHtml(badge)}</span>
                  <div class="inv-card__title">${escapeHtml(partName)}</div>
                  <div class="inv-card__meta">${escapeHtml(meta || '—')}</div>
                  ${desc ? `<div class="inv-card__desc">${escapeHtml(desc)}</div>` : ''}
                </article>`;
              })
              .join('');
          }
        }

        if (!mechData) {
          document.getElementById('ui-mech-ap').textContent = '0 / 0';
          document.getElementById('ui-mech-struct').textContent = '0 / 0';
          document.getElementById('ui-mech-shield').textContent = '0 / 0';
          document.getElementById('ui-mech-tier').textContent = '—';
          document.getElementById('ui-mech-type').textContent = '—';
          document.getElementById('ui-mech-style').textContent = '—';
          document.getElementById('ui-mech-thrust').textContent = '0.00';
          document.getElementById('ui-mech-thrust-bonus').textContent = '0';
          document.getElementById('ui-mech-ewr').textContent = '0';
          document.getElementById('ui-mech-sensor').textContent = '0';
          document.getElementById('ui-mech-duration').textContent = '0';
          return;
        }

        const overview = mechData.机甲总览 || {};
        const armor = overview.装甲值 || {};
        const struct = overview.结构值 || {};
        const shield = overview.珂若尔护盾 || {};

        document.getElementById('ui-mech-ap').textContent = `${fmtNum(armor.现 ?? 0)} / ${fmtNum(armor.满 ?? 0)}`;
        document.getElementById('ui-mech-struct').textContent = `${fmtNum(struct.现 ?? 0)} / ${fmtNum(struct.满 ?? 0)}`;
        document.getElementById('ui-mech-shield').textContent = `${fmtNum(shield.现 ?? 0)} / ${fmtNum(shield.满 ?? 0)}`;
        document.getElementById('ui-mech-tier').textContent =
          overview.装甲等级 != null && overview.装甲等级 !== '' ? String(overview.装甲等级) : '—';
        document.getElementById('ui-mech-type').textContent =
          overview.机体类型 != null && overview.机体类型 !== '' ? String(overview.机体类型) : '—';
        document.getElementById('ui-mech-style').textContent =
          overview.战斗风格 != null && overview.战斗风格 !== '' ? String(overview.战斗风格) : '—';
        document.getElementById('ui-mech-thrust').textContent =
          overview.推重比 != null && overview.推重比 !== '' ? String(overview.推重比) : '0.00';
        document.getElementById('ui-mech-thrust-bonus').textContent =
          overview.推重加值 != null && overview.推重加值 !== '' ? String(overview.推重加值) : '0';
        document.getElementById('ui-mech-ewr').textContent =
          overview.电子战评级 != null && overview.电子战评级 !== '' ? String(overview.电子战评级) : '0';
        document.getElementById('ui-mech-sensor').textContent =
          overview.观测效益 != null && overview.观测效益 !== '' ? String(overview.观测效益) : '0';
        document.getElementById('ui-mech-duration').textContent =
          overview.续航回合数 != null && overview.续航回合数 !== '' ? String(overview.续航回合数) : '0';
      }

      async function fetchAndRenderData() {
        try {
          // 1. 获取最新消息ID
          if (typeof getLastMessageId !== 'function') return;
          const lastId = getLastMessageId();

          // 2. 获取AI消息
          if (typeof getChatMessages !== 'function') return;
          let msgs = getChatMessages('0-' + lastId, { role: 'assistant' });
          if (!msgs || msgs.length === 0) {
            msgs = getChatMessages(-1, { role: 'assistant' });
          }
          if (!msgs || msgs.length === 0) return;
          const targetMsg = msgs[msgs.length - 1];

          // 3. 提取变量数据
          let rawData = null;
          if (typeof Mvu !== 'undefined' && typeof Mvu.getMvuData === 'function') {
            rawData = Mvu.getMvuData({ type: 'message', message_id: targetMsg.message_id });
          } else if (typeof getVariables === 'function') {
            rawData = getVariables({ type: 'message', message_id: targetMsg.message_id });
          }

          if (!rawData) return;

          const data = normalizeMvuRoot(rawData);
          if (!data || typeof data !== 'object') return;

          // 4. 渲染 UI
          renderUI(data);
        } catch (error) {
          console.error('AC6 UI Data Fetch Error:', error);
        }
      }

      function renderUI(data) {
        // --- 顶部资源 ---
        document.getElementById('ui-cage').innerText = fmtNum(getVal(data, '主角.资金.CAGE', 0));
        document.getElementById('ui-krl').innerText = getVal(data, '主角.驾驶属性.KRL等级', 1);

        // --- 状态总览 ---
        const rankText = getVal(data, '主角.驾驶属性.驾驶分档', '—');
        document.getElementById('ui-pilot-rank').innerText = rankText;

        const hp = Number(getVal(data, '主角.主角状态栏.HP值', 100));
        const hpEl = document.getElementById('ui-hp');
        const barHp = document.getElementById('bar-hp');
        const barHpTrack = document.getElementById('bar-hp-track');
        hpEl.innerText = String(hp);
        barHp.style.width = `${hp}%`;
        barHp.classList.toggle('hud-bar-fill--alert', hp < 30);
        barHpTrack.setAttribute('aria-valuenow', String(hp));

        const sp = Number(getVal(data, '主角.主角状态栏.SP值', 100));
        document.getElementById('ui-sp').innerText = String(sp);
        document.getElementById('bar-sp').style.width = `${sp}%`;
        document.getElementById('bar-sp-track').setAttribute('aria-valuenow', String(sp));

        document.getElementById('ui-apm').innerText = String(getVal(data, '主角.驾驶属性.APM', 0));
        const syncRate = Number(getVal(data, '主角.驾驶属性.神经同步率', 0));
        const syncMax = Number(getVal(data, '主角.驾驶属性._最大同步上限', 60)) || 60;
        const syncPct = syncMax > 0 ? Math.min(100, (syncRate / syncMax) * 100) : 0;
        document.getElementById('ui-sync').innerText = `${syncRate} / ${syncMax}%`;
        const barSync = document.getElementById('bar-sync');
        const barSyncTrack = document.getElementById('bar-sync-track');
        barSync.style.width = `${syncPct}%`;
        barSyncTrack.setAttribute('aria-valuemax', String(syncMax));
        barSyncTrack.setAttribute('aria-valuenow', String(Math.round(syncRate)));

        const shieldCur = Number(getVal(data, '主角.珂若尔护盾.现', 10));
        const shieldMax = Number(getVal(data, '主角.珂若尔护盾.满', 10));
        document.getElementById('ui-shield-cur').innerText = String(shieldCur);
        document.getElementById('ui-shield-max').innerText = String(shieldMax);
        const shieldPct = shieldMax > 0 ? (shieldCur / shieldMax) * 100 : 0;
        const barShield = document.getElementById('bar-shield');
        const barShieldTrack = document.getElementById('bar-shield-track');
        barShield.style.width = `${shieldPct}%`;
        barShield.classList.toggle('hud-bar-fill--alert', shieldPct < 30 && shieldMax > 0);
        barShieldTrack.setAttribute('aria-valuemax', String(shieldMax));
        barShieldTrack.setAttribute('aria-valuenow', String(shieldCur));

        const syncActive = Boolean(getVal(data, '交感同操.启用状态', false));
        const syncStatusEl = document.getElementById('ui-sync-status');
        if (syncActive) {
          syncStatusEl.innerText = '在线';
          syncStatusEl.classList.remove('status-metric__value--dim');
          syncStatusEl.classList.add('status-metric__value--online');
        } else {
          syncStatusEl.innerText = '离线';
          syncStatusEl.classList.add('status-metric__value--dim');
          syncStatusEl.classList.remove('status-metric__value--online');
        }
        const effRaw = getVal(data, '交感同操.共鸣效率', '—');
        const effEl = document.getElementById('ui-sync-eff');
        const effDisp = effRaw === '-' || effRaw === undefined || effRaw === null ? '—' : String(effRaw);
        effEl.innerText = effDisp;
        effEl.classList.toggle('status-metric__value--dim', effDisp === '—');

        const contactType = getVal(data, '交感同操.接触方式', '—');
        const contactTypeEl = document.getElementById('ui-contact-type');
        const contactDisp =
          contactType === '-' || contactType === undefined || contactType === null ? '—' : String(contactType);
        contactTypeEl.innerText = contactDisp;
        contactTypeEl.classList.toggle('status-metric__value--dim', contactDisp === '—');
        contactTypeEl.classList.toggle('status-metric__value--online', contactDisp !== '—');

        // --- AC 整备（机库 · stat_data 咬合 + 可用机甲部件） ---
        renderGarageSection(data);

        // --- 通讯频道 · 立绘交互 ---
        renderCommsPortraits(data);

        // --- 作战与行动 ---
        const missionsData = getVal(data, '任务面板', {});
        const missionListEl = document.getElementById('ui-mission-list');
        let missionHtml = '';

        if (Object.keys(missionsData).length > 0) {
          for (const [id, mission] of Object.entries(missionsData)) {
            let statusColor = 'var(--ac-base)';
            if (mission.进行状态 === '进行中') statusColor = 'var(--ac-light)';
            if (mission.进行状态 === '已完成') statusColor = '#4ae28a';
            if (mission.进行状态 === '失败') statusColor = 'var(--ac-alert)';

            missionHtml += `
                    <div class="mission-card panel-chamfer">
                        <div style="flex: 1;">
                            <div style="display: flex; justify-content: space-between; align-items: center;">
                                <div>
                                    <span class="mission-title">${mission.任务名称 || 'UNKNOWN MISSION'}</span>
                                    <span class="mission-type">${mission.任务类型 || '-'}</span>
                                </div>
                                <span class="mission-status" style="color: ${statusColor};">${mission.进行状态 || 'STANDBY'}</span>
                            </div>
                            ${
                              mission.目标列表 && mission.目标列表.length > 0
                                ? `
                            <div style="font-size: 12px; color: var(--ac-base); margin-top: 5px;">
                                目标: ${mission.目标列表.join(' | ')}
                            </div>`
                                : ''
                            }
                            <div style="font-size: 12px; margin-top: 3px;">
                                <span style="color: var(--ac-base);">奖励:</span>
                                <span>${mission.奖励资金 || 0} CAGE</span>
                                ${mission.奖励经验 ? `<span style="margin-left: 10px;">${mission.奖励经验} EXP</span>` : ''}
                            </div>
                        </div>
                    </div>
                `;
          }
        } else {
          missionHtml = `
                <div class="mission-card panel-chamfer">
                    <div style="flex:1; text-align: center; opacity: 0.4; padding: 20px 0;">
                        <i data-lucide="target" size="24" style="margin-bottom: 5px;"></i>
                        <div><span class="mission-title">NO ACTIVE MISSIONS</span></div>
                        <span class="mission-status" style="color: var(--ac-base);">STANDBY</span>
                    </div>
                </div>
            `;
        }
        missionListEl.innerHTML = missionHtml;
        // 重新初始化新增图标的 lucide
        lucide.createIcons();
      }
      // ================= 通讯频道 · 立绘交互逻辑 =================

      let portraitSlotsInitialized = false;

      // 角色立绘图片映射（每个角色多张姿态图）
      const PORTRAIT_IMAGES = {
        艾尔: [
          'https://cdn.imgchest.com/files/f54ecdab32fa.png',
          'https://cdn.imgchest.com/files/5232454620c6.png',
          'https://cdn.imgchest.com/files/958f4f21c921.png',
          'https://cdn.imgchest.com/files/f2063b731541.png',
        ],
        ALLMIND: [
          'https://cdn.imgchest.com/files/a740ccf50b67.png',
          'https://cdn.imgchest.com/files/88c87b34b9cd.png',
          'https://cdn.imgchest.com/files/131d9ee1fc2b.png',
          'https://cdn.imgchest.com/files/422d9bd2398d.png',
        ],
        莉娜_许奈德: [
          'https://cdn.imgchest.com/files/485d5431b9cd.png',
          'https://cdn.imgchest.com/files/84cc2a2a3100.png',
          'https://cdn.imgchest.com/files/df8f0c3a66c3.png',
          'https://cdn.imgchest.com/files/c1775ce2a102.png',
        ],
        曹奕奕: [
          'https://cdn.imgchest.com/files/497451fd0739.png',
          'https://cdn.imgchest.com/files/d417fa5043e9.png',
          'https://cdn.imgchest.com/files/d0c9a6d4546b.png',
        ],
        林芿: [
          'https://cdn.imgchest.com/files/fa1f0ddead7e.png',
          'https://cdn.imgchest.com/files/b3a8f97f2250.png',
          'https://cdn.imgchest.com/files/31614797fa7c.png',
        ],
        邰鸾: [
          'https://cdn.imgchest.com/files/623b1c76e583.png',
          'https://cdn.imgchest.com/files/f5d057e7b770.png',
          'https://cdn.imgchest.com/files/4c28f7b89b88.png',
        ],
        利荔: ['https://cdn.imgchest.com/files/6e59d6be47e7.png', 'https://cdn.imgchest.com/files/f164356a5bd9.png'],
      };

      // 记录每个角色的当前立绘索引
      const portraitIndex = {};
      for (const key of Object.keys(PORTRAIT_IMAGES)) {
        portraitIndex[key] = 0;
      }

      // 页面加载时预加载所有立绘图片，避免首次切换时因 CDN 下载延迟导致卡顿
      function preloadAllPortraits() {
        for (const images of Object.values(PORTRAIT_IMAGES)) {
          for (const src of images) {
            const img = new Image();
            img.src = src;
          }
        }
      }
      preloadAllPortraits();

      // 当前展开的立绘槽位 ID（同一时间只展开一个）
      let expandedSlotId = null;

      // 初始化立绘点击事件
      function initPortraitSlots() {
        const slots = document.querySelectorAll('.portrait-slot');
        slots.forEach(slot => {
          slot.addEventListener('click', e => {
            // 忽略切换按钮的冒泡（按钮有自己的 onclick）
            const contactId = slot.dataset.contactId;
            togglePortraitSlot(contactId);
          });
        });
        portraitSlotsInitialized = true;
      }

      /** 仅在立绘横条内横向滚动，避免 scrollIntoView 带动整页/iframe 视口偏移 */
      function scrollPortraitIntoCommsStrip(slot) {
        const strip = document.getElementById('comms-strip');
        if (!strip || !slot || !strip.contains(slot)) return;
        const slotLeftInContent =
          slot.getBoundingClientRect().left - strip.getBoundingClientRect().left + strip.scrollLeft;
        const target = slotLeftInContent - (strip.clientWidth - slot.offsetWidth) / 2;
        const maxScroll = Math.max(0, strip.scrollWidth - strip.clientWidth);
        strip.scrollTo({ left: Math.max(0, Math.min(target, maxScroll)), behavior: 'smooth' });
      }

      // 切换/展开立绘槽位
      function togglePortraitSlot(contactId) {
        const slot = document.querySelector(`.portrait-slot[data-contact-id="${contactId}"]`);
        if (!slot) return;

        if (expandedSlotId === contactId) {
          // 再次点击则收起
          collapseSlot(slot, contactId);
          expandedSlotId = null;
        } else {
          // 先收起已展开的
          if (expandedSlotId) {
            const prevSlot = document.querySelector(`.portrait-slot[data-contact-id="${expandedSlotId}"]`);
            if (prevSlot) collapseSlot(prevSlot, expandedSlotId);
          }
          // 展开新的
          expandSlot(slot, contactId);
          expandedSlotId = contactId;
          requestAnimationFrame(() => scrollPortraitIntoCommsStrip(slot));
        }
      }

      // 展开立绘槽位
      function expandSlot(slot, contactId) {
        slot.classList.add('expanded');
        // 更新进度条（从 data 属性读取当前值）
        const favor = parseFloat(slot.dataset.favor || 0);
        const rapport = parseFloat(slot.dataset.rapport || 0);
        updatePortraitBars(contactId, favor, rapport);
      }

      // 收起立绘槽位
      function collapseSlot(slot, contactId) {
        slot.classList.remove('expanded');
      }

      // 更新立绘槽位的进度条
      function updatePortraitBars(contactId, favor, rapport) {
        const slot = document.querySelector(`.portrait-slot[data-contact-id="${contactId}"]`);
        if (!slot) return;

        const favorBar = document.getElementById(`bar-favor-${contactId}`);
        const rapportBar = document.getElementById(`bar-rapport-${contactId}`);
        const favorVal = document.getElementById(`val-favor-${contactId}`);
        const rapportVal = document.getElementById(`val-rapport-${contactId}`);

        // 好感度上限 100
        const favorPct = Math.min(100, Math.max(0, favor));
        const rapportPct = Math.min(100, Math.max(0, rapport));

        if (favorBar) favorBar.style.width = `${favorPct}%`;
        if (rapportBar) rapportBar.style.width = `${rapportPct}%`;
        if (favorVal) favorVal.textContent = Math.round(favor);
        if (rapportVal) rapportVal.textContent = Math.round(rapport);
      }

      // 循环切换立绘姿态
      window.cyclePortrait = function (event, contactId) {
        event.stopPropagation();
        event.preventDefault();

        const images = PORTRAIT_IMAGES[contactId];
        if (!images || images.length <= 1) return;

        portraitIndex[contactId] = (portraitIndex[contactId] + 1) % images.length;
        const slot = document.querySelector(`.portrait-slot[data-contact-id="${contactId}"]`);
        const img = slot?.querySelector('.portrait-img');
        if (img) {
          // 短暂淡出再切换
          img.style.opacity = '0';
          setTimeout(() => {
            img.src = images[portraitIndex[contactId]];
            img.style.opacity = '1';
          }, 150);
        }
      };

      // 渲染通讯频道立绘数据
      function renderCommsPortraits(data) {
        const commsData = getVal(data, '红颜通讯', {});
        const commsStrip = document.getElementById('comms-strip');
        if (!commsStrip) return;

        // 更新每个固定槽位的数据
        const slotIds = ['艾尔', 'ALLMIND', '莉娜_许奈德', '曹奕奕', '林芿', '邰鸾', '利荔'];

        for (const contactId of slotIds) {
          const slot = commsStrip.querySelector(`.portrait-slot[data-contact-id="${contactId}"]`);
          if (!slot) continue;

          const info = commsData[contactId] || {};
          const name = info.角色名称 || slot.dataset.name || contactId;
          const favor = Number(info.好感度 ?? 0);
          const rapport = Number(info.默契度 ?? 0);
          const phase = info.关系阶段 || '';

          // 更新 data 属性（供展开动画时读取）
          slot.dataset.favor = favor;
          slot.dataset.rapport = rapport;

          // 更新名称（如果已展开则保持动画状态）
          const nameEl = slot.querySelector('.portrait-name');
          if (nameEl) nameEl.textContent = name;

          // 实时更新进度条（始终反映最新数值）
          updatePortraitBars(contactId, favor, rapport);
        }

        // 重新初始化 lucide 图标（进度条内的 heart/link icon）
        lucide.createIcons();
      }

      // 立即初始化立绘槽位（HTML 是静态结构，脚本执行时 DOM 已就绪）
      initPortraitSlots();

      // 页面加载时无需额外初始化（保留 DOMContentLoaded 作为保险）
      document.addEventListener('DOMContentLoaded', () => {
        if (!portraitSlotsInitialized) {
          initPortraitSlots();
          portraitSlotsInitialized = true;
        }
      });

      // 事件驱动更新：仅在新消息楼层出现或生成结束时刷新 UI，摒弃低效的 2 秒轮询
      eventOn(tavern_events.MESSAGE_RECEIVED, (messageId, type) => {
        if (type !== 'quiet') {
          fetchAndRenderData();
        }
      });
      // 流式生成结束后再刷新一次，确保最终状态完整
      eventOn(tavern_events.GENERATION_ENDED, () => {
        fetchAndRenderData();
      });
      // 初始执行一次
      setTimeout(fetchAndRenderData, 500);
    </script>
  </body>
</html>
