    <script>
      (function() {
        const core = document.currentScript.closest('.ac6-mech-core');
        const rawType = core.querySelector('.raw-type').textContent.trim();
        const raw = core.querySelector('.raw-data').textContent;
        const dest = core.querySelector('.ac6-content');
        const titleEl = core.querySelector('#dynamic-title');

        if (rawType === 'mech_group') {
          titleEl.textContent = 'GROUP PROFILE';
        }

        let html = '';
        let thinkContent = '';
        let inBlockComment = false;

        // ── YAML inline object renderer ──────────────────────────────────────
        function renderYamlObj(objStr) {
          var result = '<span class="yaml-obj">';
          var parts = objStr.split(',');
          for (var i = 0; i < parts.length; i++) {
            var kv = parts[i].trim();
            var colonIdx = kv.indexOf(':');
            if (colonIdx === -1) {
              result += '<span class="yaml-val">' + escHtml(kv) + '</span>';
            } else {
              var k = kv.substring(0, colonIdx).trim();
              var v = kv.substring(colonIdx + 1).trim();
              result += '<span class="yaml-key">' + escHtml(k) + '</span><span class="yaml-sep">: </span><span class="yaml-val">' + escHtml(v) + '</span>';
            }
            if (i < parts.length - 1) result += '<span class="yaml-sep">, </span>';
          }
          return result + '</span>';
        }

        function escHtml(s) {
          return String(s)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;');
        }

        var lines = raw.split('\n');
        for (var i = 0; i < lines.length; i++) {
          var line = lines[i];
          var rawLine = line;       // original (for indent calc)
          var t = line.trim();
          if (!t) continue;

          // ── Block comment: <!-- ... --> ──────────────────────────────────
          if (t.startsWith('<!--')) {
            inBlockComment = true;
            t = t.replace('<!--', '').trim();
          }
          if (inBlockComment) {
            var ends = t.endsWith('-->');
            t = t.replace('-->', '').trim();
            // YAML comments inside block comments
            if (t.startsWith('#')) t = t.substring(1).trim();
            if (t && t.indexOf('mechThink') === -1) {
              thinkContent += t + '<br>';
            }
            if (ends) {
              inBlockComment = false;
              if (thinkContent) {
                html += '<div class="ui-think-box"><div class="ui-think-hdr">SYS.THOUGHT // TACTICAL_EVAL</div><div class="ui-think-body">' + thinkContent + '</div></div>';
                thinkContent = '';
              }
            }
            continue;
          }

          // ── YAML comments (lines starting with #) ─────────────────────────
          if (t.charAt(0) === '#') {
            var commentText = t.substring(1).trim();
            if (commentText && commentText.indexOf('mechThink') === -1) {
              thinkContent += commentText + '<br>';
            }
            continue;
          }

          // ── YAML block end marker (---) ───────────────────────────────────
          if (t === '---') {
            if (thinkContent) {
              html += '<div class="ui-think-box"><div class="ui-think-hdr">SYS.THOUGHT // TACTICAL_EVAL</div><div class="ui-think-body">' + thinkContent + '</div></div>';
              thinkContent = '';
            }
            continue;
          }

          // ── YAML document start marker (...) ───────────────────────────────
          if (t === '...' || t === '---') {
            continue;
          }

          // ── Determine indent level (2 spaces = 1 level) ───────────────────
          var leadingSpaces = rawLine.match(/^(\s*)/);
          var indent = leadingSpaces ? Math.floor(leadingSpaces[1].length / 2) : 0;
          var marginLeft = indent * 16;

          // ── 顶级区块标题 (e.g. "机甲档案:") ──────────────────────────────
          // Matches a line whose non-space content ends with :
          // but is NOT a list item (not preceded by - ) and NOT an inline value
          var nonSpace = rawLine.replace(/^\s+/, '');
          if (nonSpace === t && /^[^ \t\-#][^:]*:$/.test(t)) {
            // It's a top-level section header (no leading dash, no hash, ends with colon)
            html += '<div class="ui-section"><div class="ui-sec-dec"></div><div class="ui-sec-text">' + escHtml(t.replace(/:$/, '')) + '</div></div>';
            continue;
          }

          // ── List + key:value (e.g. "- 武器名: 高周波振荡短刀对剑") ──────
          var listKvMatch = rawLine.match(/^(\s*)-\s+([^:]+):\s*(.*)$/);
          if (listKvMatch) {
            var k = listKvMatch[2].trim();
            var v = listKvMatch[3].trim();
            var valHtml = renderYamlVal(v);
            html += '<div class="ui-list-kv" style="margin-left:' + marginLeft + 'px"><div class="ui-li-hex"></div><div class="ui-kv-key">' + escHtml(k) + '</div><div class="ui-kv-val">' + valHtml + '</div></div>';
            continue;
          }

          // ── Pure list item (e.g. "- 双持连击，依靠机体高速突进拉近距离后切割") ──
          var pureListMatch = rawLine.match(/^(\s*)-\s+(.*)$/);
          if (pureListMatch) {
            var itemText = pureListMatch[2].trim();
            // Skip block scalar markers
            if (itemText === '|' || itemText === '>' || itemText === '|-' || itemText === '>-' || itemText === '|' || itemText === '>-') continue;
            html += '<div class="ui-list-item" style="margin-left:' + marginLeft + 'px"><div class="ui-li-line"></div><div class="ui-li-text">' + escHtml(itemText) + '</div></div>';
            continue;
          }

          // ── Standard key:value (e.g. "推重比: 5.2" or "装甲值: {现: 180, 满: 180}") ──
          var kvMatch = rawLine.match(/^(\s*)([^#:\-][^:]*):\s*(.*)$/);
          if (kvMatch) {
            var kvKey = kvMatch[2].trim();
            var kvVal = kvMatch[3].trim();
            // Skip YAML directives and anchors
            if (kvKey === '%YAML' || kvKey === '%TAG' || kvKey.charAt(0) === '&' || kvKey.charAt(0) === '*') continue;
            // Remove trailing inline comment
            var commentIdx = kvVal.indexOf(' #');
            if (commentIdx !== -1) kvVal = kvVal.substring(0, commentIdx).trim();
            if (kvVal === '' || kvVal === '|' || kvVal === '>' || kvVal === '|-' || kvVal === '>-') {
              html += '<div class="ui-nested-hdr" style="margin-left:' + marginLeft + 'px">' + escHtml(kvKey) + '</div>';
            } else {
              var renderedVal = renderYamlVal(kvVal);
              html += '<div class="ui-kv" style="margin-left:' + marginLeft + 'px"><div class="ui-kv-key">' + escHtml(kvKey) + '</div><div class="ui-kv-val">' + renderedVal + '</div></div>';
            }
            continue;
          }

          // ── YAML block scalar (| or >) continuation ───────────────────────
          var blockMatch = rawLine.match(/^(\s*)(\||>)([-+]?)\s*$/);
          if (blockMatch && i + 1 < lines.length) {
            var blockLines = [];
            var blockIndent = indent;
            for (var j = i + 1; j < lines.length; j++) {
              var bl = lines[j];
              var bleading = bl.match(/^(\s*)/);
              var bind = bleading ? Math.floor(bleading[1].length / 2) : 0;
              if (bl.trim() === '' || bind > blockIndent) {
                blockLines.push(bl.replace(/^\s*/, ''));
              } else {
                break;
              }
            }
            if (blockLines.length > 0) {
              html += '<div class="ui-list-item" style="margin-left:' + marginLeft + 'px"><div class="ui-li-line"></div><div class="ui-li-text">' + escHtml(blockLines.join(' ')) + '</div></div>';
              i = j - 1;
            }
            continue;
          }

          // ── Fallback plain text ───────────────────────────────────────────
          html += '<div class="ui-text" style="margin-left:' + marginLeft + 'px">' + escHtml(t) + '</div>';
        }

        // ── Flush any remaining think content ────────────────────────────────
        if (thinkContent) {
          html = '<div class="ui-think-box"><div class="ui-think-hdr">SYS.THOUGHT // TACTICAL_EVAL</div><div class="ui-think-body">' + thinkContent + '</div></div>' + html;
        }

        dest.innerHTML = html;

        // ── YAML value renderer (inline objects, numbers, quoted strings) ──────
        function renderYamlVal(v) {
          v = v.trim();
          // Quoted strings
          if ((v.charAt(0) === '"' && v.charAt(v.length - 1) === '"') ||
              (v.charAt(0) === "'" && v.charAt(v.length - 1) === "'")) {
            return escHtml(v.slice(1, -1));
          }
          // Inline object: { key: val, key: val }
          if (v.charAt(0) === '{' && v.charAt(v.length - 1) === '}') {
            return renderYamlObj(v.slice(1, -1));
          }
          // Inline array: [ a, b, c ]
          if (v.charAt(0) === '[' && v.charAt(v.length - 1) === ']') {
            var inner = v.slice(1, -1).trim();
            if (!inner) return '<span class="yaml-val"></span>';
            var items = [];
            var depth = 0, last = 0;
            for (var ci = 0; ci < inner.length; ci++) {
              if (inner.charAt(ci) === '[' || inner.charAt(ci) === '{') depth++;
              else if (inner.charAt(ci) === ']' || inner.charAt(ci) === '}') depth--;
              else if (inner.charAt(ci) === ',' && depth === 0) {
                items.push(inner.substring(last, ci).trim());
                last = ci + 1;
              }
            }
            items.push(inner.substring(last).trim());
            var arrHtml = '<span class="yaml-obj">';
            for (var ai = 0; ai < items.length; ai++) {
              arrHtml += '<span class="yaml-val">' + escHtml(items[ai]) + '</span>';
              if (ai < items.length - 1) arrHtml += '<span class="yaml-sep">, </span>';
            }
            return arrHtml + '</span>';
          }
          return escHtml(v);
        }
      })();

      function toggleCore(el) {
        var core = el.closest('.ac6-mech-core');
        if (core) {
          core.classList.toggle('active');
          setTimeout(updateHeight, 550);
          updateHeight();
        }
      }
      function updateHeight() {
        if (window.parent && window.parent !== window) {
          window.parent.postMessage({ type: 'resizeIframe', height: document.body.scrollHeight }, '*');
        }
      }
      window.addEventListener('load', function() {
        setTimeout(updateHeight, 100);
      });
      var resizeObserver = new ResizeObserver(function() { updateHeight(); });
      resizeObserver.observe(document.body);
    </script>
  </div>
</body>
