        const dest = core.querySelector('.ac6-content');

        function esc(s) {
          return String(s)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;');
        }
        function fmt(s) {
          return esc(s).replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
