      position: fixed; inset: 0; z-index: 1; pointer-events: none;
      background: repeating-linear-gradient(
        0deg,
        transparent,
        transparent 2px,
        rgba(0,0,0,0.15) 2px,
        rgba(0,0,0,0.15) 4px
      );
    }

    /* ─── LAYOUT ─── */
    #app {
      position: relative; z-index: 2;
      width: 100%; height: 100%;
      display: flex;
      flex-direction: column;
      overflow: hidden;
    }

    /* ─── TOP BAR ─── */
    #topbar {
      flex-shrink: 0;
      display: flex; align-items: center; justify-content: space-between;
      padding: 8px 16px;
      background: var(--c-panel);
      border-bottom: 1px solid var(--c-primary);
      backdrop-filter: blur(8px);
    }
    #topbar-title {
      font-family: var(--font-mono);
      font-size: 11px;
      color: var(--c-accent2);
      letter-spacing: 2px;
    }
    #topbar-title span { color: var(--c-muted); }
    .blink { animation: blink 1.2s step-end infinite; }
    @keyframes blink { 50% { opacity: 0; } }

    #topbar-actions { display: flex; gap: 8px; align-items: center; }
    .btn-walter {
      font-family: var(--font-mono);
      font-size: 10px;
      color: var(--c-warn);
      background: transparent;
      border: 1px solid var(--c-warn);
      padding: 4px 10px;
      cursor: pointer;
      letter-spacing: 1px;
      transition: all 0.15s;
    }
    .btn-walter:hover { background: rgba(224,160,32,0.12); }

    /* ─── MAIN AREA ─── */
    #main {
      flex: 1;
      display: flex;
      overflow: hidden;
      position: relative;
    }

    /* ─── TAB CONTENT ─── */
    #content {
      flex: 1;
      overflow-y: auto;
      overflow-x: hidden;
      padding: 12px 16px 80px;
      scrollbar-width: thin;
      scrollbar-color: var(--c-primary) var(--c-bg);
    }
    #content::-webkit-scrollbar { width: 4px; }
    #content::-webkit-scrollbar-track { background: var(--c-bg); }
    #content::-webkit-scrollbar-thumb { background: var(--c-primary); }

    .tab-page { display: none; }
    .tab-page.active { display: block; }

    /* ─── SECTION HEADER ─── */
    .sec-header {
      font-family: var(--font-mono);
      font-size: 10px;
      color: var(--c-accent);
      letter-spacing: 3px;
      margin-bottom: 12px;
      padding-bottom: 6px;
      border-bottom: 1px solid var(--c-line);
      display: flex; align-items: center; gap: 8px;
    }
    .sec-header::before {
      content: '//';
      color: var(--c-primary);
    }
    .sec-header .badge {
      margin-left: auto;
      font-size: 9px;
      color: var(--c-muted);
      border: 1px solid var(--c-border);
      padding: 1px 5px;
    }

    /* ─── FORM GRID ─── */
    .form-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
      gap: 10px;
      margin-bottom: 16px;
    }
    .form-row {
      display: flex; flex-direction: column; gap: 4px;
    }
    .form-row label {
      font-family: var(--font-mono);
      font-size: 10px;
      color: var(--c-muted);
      letter-spacing: 1px;
      text-transform: uppercase;
    }
    .form-row input, .form-row select, .form-row textarea {
      background: rgba(18, 148, 131, 0.05);
      border: 1px solid var(--c-border);
      color: var(--c-white);
      padding: 6px 8px;
      font-family: var(--font-mono);
      font-size: 12px;
      outline: none;
      width: 100%;
      transition: border-color 0.15s, background 0.15s;
    }
    .form-row input:focus, .form-row select:focus, .form-row textarea:focus {
      border-color: var(--c-primary);
      background: rgba(18, 148, 131, 0.1);
    }
    .form-row select option { background: #0a1a1c; }

    /* ─── STAT DISPLAY ─── */
    .stat-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
      gap: 8px;
      margin-bottom: 16px;
    }
    .stat-item {
      background: var(--c-panel2);
      border: 1px solid var(--c-border);
      padding: 8px 10px;
      display: flex; flex-direction: column; gap: 2px;
    }
    .stat-item .stat-label {
      font-family: var(--font-mono);
      font-size: 9px;
      color: var(--c-muted);
      letter-spacing: 1px;
    }
    .stat-item .stat-val {
      font-family: var(--font-mono);
      font-size: 16px;
      color: var(--c-accent2);
      font-weight: 700;
    }
    .stat-item .stat-val.warn { color: var(--c-warn); }
    .stat-item .stat-val.ok   { color: var(--c-accent); }

    /* ─── SLOT GRID (PAGE2) ─── */
    #ac-layout {
      display: grid;
      grid-template-areas:
        "head  head  head"
        "ra    img   rb"
        "la    img   lb"
        "core  img   fcs"
        "hands img   engine"
        "legs  boost ext";
      grid-template-columns: 1fr 1.4fr 1fr;
      grid-template-rows: auto;
      gap: 6px;
      margin-bottom: 16px;
    }
    #slot-head    { grid-area: head; }
    #slot-ra      { grid-area: ra; }
    #slot-la      { grid-area: la; }
    #slot-rb      { grid-area: rb; }
    #slot-lb      { grid-area: lb; }
    #slot-core    { grid-area: core; }
    #slot-fcs     { grid-area: fcs; }
    #slot-hands   { grid-area: hands; }
    #slot-engine  { grid-area: engine; }
    #slot-legs    { grid-area: legs; }
    #slot-boost   { grid-area: boost; }
    #slot-ext     { grid-area: ext; }
    #ac-center    { grid-area: img; display: absolute; z-index: 10; gap: 4px; }
    #ac-center img {
      width: 100%;
      max-height: 240px;
      object-fit: contain;
      filter: brightness(0.9) saturate(0.7) hue-rotate(-10deg);
      border: 1px solid var(--c-border);
    }
    #ac-type-select {
      width: 100%;
      background: var(--c-panel2);
      border: 1px solid var(--c-border);
      color: var(--c-text);
      padding: 4px 6px;
      font-family: var(--c-text);
      font-size: 14px;
      letter-spacing: 1px;
      outline: none;
    }

    #ac-type-select:hover {
      border-color: var(--c-primary);
      background: rgba(18,148,131,0.12);
    }

    #ac-type-select option {
      background-color: var(--c-bg);
      color: var(--c-text);
      padding: 5px;
    }

    .slot-btn {
      width: 100%;
      background: var(--c-panel2);
      border: 1px solid var(--c-border);
      color: var(--c-text);
      padding: 8px 10px;
      cursor: pointer;
      text-align: left;
      transition: all 0.15s;
      position: relative;
      overflow: hidden;
    }
    .slot-btn:hover {
      border-color: var(--c-primary);
      background: rgba(18,148,131,0.12);
    }
    .slot-btn .slot-tag {
      font-family: var(--font-mono);
      font-size: 9px;
      color: var(--c-primary);
      letter-spacing: 1px;
      display: block;
    }
    .slot-btn .slot-name {
      font-family: var(--font-mono);
      font-size: 11px;
      color: var(--c-white);
      display: block;
      margin-top: 2px;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }
    .slot-btn .slot-sub {
      font-size: 10px;
      color: var(--c-muted);
      display: block;
      margin-top: 1px;
      font-family: var(--font-mono);
    }
    .slot-btn.filled { border-color: var(--c-line); }
    .slot-btn.filled .slot-tag { color: var(--c-accent); }

    /* ─── INTEGRATED STATS (right panel) ─── */
    #integrated-stats {
      background: var(--c-panel2);
      border: 1px solid var(--c-border);
      padding: 10px;
      margin-bottom: 12px;
    }
    .istat-row {
      display: flex; justify-content: space-between; align-items: center;
      padding: 4px 0;
      border-bottom: 1px solid rgba(30,74,74,0.4);
    }
    .istat-row:last-child { border-bottom: none; }
    .istat-label {
      font-family: var(--font-mono);
      font-size: 10px;
      color: var(--c-muted);
    }
    .istat-val {
      font-family: var(--font-mono);
      font-size: 11px;
      color: var(--c-accent2);
    }
    .istat-bar {
      height: 3px;
      background: var(--c-border);
      margin-top: 2px;
      width: 100%;
    }
    .istat-bar-fill {
      height: 100%;
      background: var(--c-primary);
      transition: width 0.3s;
    }

    /* ─── BOTTOM NAV ─── */
    #bottom-nav {
      position: fixed; bottom: 0; left: 0; right: 0;
      z-index: 10;
      display: flex;
      background: var(--c-panel);
      border-top: 1px solid var(--c-primary);
      backdrop-filter: blur(10px);
    }
    .nav-tab {
      flex: 1;
      padding: 10px 4px;
      background: transparent;
      border: none;
      color: var(--c-muted);
      font-family: var(--font-mono);
      font-size: 10px;
      letter-spacing: 1px;
      cursor: pointer;
      transition: all 0.15s;
      border-right: 1px solid var(--c-border);
      text-align: center;
    }
    .nav-tab:last-child { border-right: none; }
    .nav-tab.active {
      color: var(--c-accent2);
      background: rgba(18,148,131,0.12);
      border-top: 2px solid var(--c-accent);
    }
    .nav-tab:hover:not(.active) { color: var(--c-text); background: rgba(18,148,131,0.06); }

    /* ─── WALTER NOTES PANEL ─── */
    #walter-panel {
      position: fixed;
      top: 0; right: -380px; bottom: 0;
      width: 360px;
      z-index: 50;
      background: rgba(4, 12, 13, 0.96);
      border-left: 1px solid var(--c-primary);
      backdrop-filter: blur(12px);
      display: flex; flex-direction: column;
      transition: right 0.25s ease;
      overflow: hidden;
    }
    #walter-panel.open { right: 0; }
    #walter-header {
      flex-shrink: 0;
      padding: 10px 14px;
      border-bottom: 1px solid var(--c-line);
      display: flex; align-items: center; justify-content: space-between;
    }
    #walter-header h3 {
      font-family: var(--font-mono);
      font-size: 11px;
      color: var(--c-warn);
      letter-spacing: 2px;
    }
    #close-walter {
      background: none; border: none; color: var(--c-muted);
      cursor: pointer; font-size: 16px; line-height: 1;
      padding: 2px 6px;
      transition: color 0.15s;
    }
    #close-walter:hover { color: var(--c-white); }
    #walter-tabs {
      flex-shrink: 0;
      display: flex;
      border-bottom: 1px solid var(--c-border);
    }
    .w-tab {
      flex: 1; padding: 7px 4px;
      background: none; border: none;
      color: var(--c-muted);
      font-family: var(--font-mono);
      font-size: 9px; letter-spacing: 1px;
      cursor: pointer;
      transition: all 0.15s;
      border-right: 1px solid var(--c-border);
    }
    .w-tab:last-child { border-right: none; }
    .w-tab.active { color: var(--c-accent); background: rgba(18,148,131,0.1); }
    #walter-content {
      flex: 1; overflow-y: auto; padding: 12px;
      scrollbar-width: thin;
      scrollbar-color: var(--c-line) transparent;
    }
    .w-page { display: none; }
    .w-page.active { display: block; }
    .ref-block {
      background: var(--c-panel2);
      border: 1px solid var(--c-border);
      padding: 10px;
      margin-bottom: 10px;
      position: relative;
    }
    .ref-block h4 {
      font-family: var(--font-mono);
      font-size: 10px; color: var(--c-accent);
      letter-spacing: 2px; margin-bottom: 8px;
    }
    .ref-table {
      width: 100%;
      border-collapse: collapse;
      font-family: var(--font-mono);
      font-size: 10px;
    }
    .ref-table th {
      color: var(--c-muted);
      border-bottom: 1px solid var(--c-border);
      padding: 3px 6px;
      text-align: left;
    }
    .ref-table td {
      color: var(--c-text);
      padding: 3px 6px;
      border-bottom: 1px solid rgba(30,74,74,0.3);
    }
    .ref-table tr:last-child td { border-bottom: none; }
    .ref-table td.hl { color: var(--c-accent2); }
    .copy-btn {
      position: absolute; top: 8px; right: 8px;
      background: transparent;
      border: 1px solid var(--c-border);
      color: var(--c-muted);
      font-family: var(--font-mono);
      font-size: 9px; padding: 2px 6px;
      cursor: pointer; letter-spacing: 1px;
      transition: all 0.15s;
    }
    .copy-btn:hover { border-color: var(--c-accent); color: var(--c-accent); }
    .ref-text {
      font-family: var(--font-mono);
      font-size: 10px;
      color: var(--c-text);
      line-height: 1.7;
      white-space: pre-wrap;
    }

    /* ─── MODAL ─── */
    #modal-overlay {
      position: fixed; inset: 0; z-index: 100;
      background: rgba(3, 8, 9, 0.88);
      display: none; align-items: center; justify-content: center;
      backdrop-filter: blur(4px);
    }
    #modal-overlay.open { display: flex; }
    #modal-box {
      background: rgba(6, 16, 18, 0.97);
      border: 1px solid var(--c-primary);
      width: min(90vw, 440px);
      max-height: 85vh;
      display: flex; flex-direction: column;
      overflow: hidden;
    }
    #modal-header {
      flex-shrink: 0;
      padding: 10px 14px;
      border-bottom: 1px solid var(--c-line);
      display: flex; align-items: center; justify-content: space-between;
    }
    #modal-title {
      font-family: var(--font-mono);
      font-size: 11px;
      color: var(--c-accent2);
      letter-spacing: 2px;
    }
    #modal-close {
      background: none; border: none; color: var(--c-muted);
      cursor: pointer; font-family: var(--font-mono); font-size: 14px;
      transition: color 0.15s; padding: 0 4px;
    }
    #modal-close:hover { color: var(--c-white); }
    #modal-body {
      flex: 1; overflow-y: auto; padding: 14px;
      scrollbar-width: thin;
      scrollbar-color: var(--c-line) transparent;
    }
    #modal-footer {
      flex-shrink: 0;
      padding: 10px 14px;
      border-top: 1px solid var(--c-line);
      display: flex; justify-content: flex-end; gap: 8px;
    }

    /* ─── BUTTONS ─── */
    .btn {
      font-family: var(--font-mono);
      font-size: 11px;
      letter-spacing: 1px;
      padding: 7px 16px;
      border: 1px solid;
      cursor: pointer;
      transition: all 0.15s;
      background: transparent;
    }
    .btn-primary {
      color: var(--c-accent2);
      border-color: var(--c-primary);
    }
    .btn-primary:hover { background: rgba(18,148,131,0.18); }
    .btn-secondary {
      color: var(--c-muted);
      border-color: var(--c-border);
    }
    .btn-secondary:hover { color: var(--c-text); border-color: var(--c-muted); }
    .btn-confirm {
      color: var(--c-bg);
      background: var(--c-primary);
      border-color: var(--c-accent);
      font-size: 12px;
      padding: 10px 28px;
    }
    .btn-confirm:hover { background: var(--c-accent); }
    .btn-danger {
      color: var(--c-danger);
      border-color: var(--c-danger);
    }
    .btn-danger:hover { background: rgba(192,64,42,0.12); }

    /* ─── CONFIRM OVERLAY ─── */
    #confirm-overlay {
      position: fixed; inset: 0; z-index: 200;
      background: rgba(3,8,9,0.96);
      display: none;
      flex-direction: column;
      align-items: center; justify-content: center;
      gap: 24px;
    }
    #confirm-overlay.open { display: flex; }
    #confirm-text {
      font-family: var(--font-mono);
      font-size: 13px;
      color: var(--c-accent);
      letter-spacing: 3px;
      text-align: center;
      line-height: 2;
    }
    #confirm-text .big {
      display: block;
      font-size: 18px;
      color: var(--c-accent2);
      margin-bottom: 8px;
      animation: pulse 1.5s ease-in-out infinite;
    }
    @keyframes pulse {
      0%,100% { opacity: 1; } 50% { opacity: 0.5; }
    }
    #confirm-text .sub {
      display: block;
      font-size: 10px;
      color: var(--c-muted);
      letter-spacing: 2px;
    }
    #confirm-preview {
      background: var(--c-panel2);
      border: 1px solid var(--c-line);
      padding: 12px 16px;
      font-family: var(--font-mono);
      font-size: 10px;
      color: var(--c-text);
      line-height: 1.8;
      max-width: 400px;
      width: 90%;
    }
    #confirm-btns { display: flex; gap: 12px; }

    /* ─── MECH NAME INPUT (PAGE2 top) ─── */
    #mech-name-row {
      display: flex; align-items: center; gap: 12px;
      margin-bottom: 14px;
    }
    #mech-name-row label {
      font-family: var(--font-mono);
      font-size: 10px;
      color: var(--c-muted);
      letter-spacing: 2px;
      white-space: nowrap;
    }
    #mech-name-input {
      flex: 1;
      background: rgba(18,148,131,0.06);
      border: 1px solid var(--c-border);
      border-bottom: 2px solid var(--c-primary);
      color: var(--c-accent2);
      font-family: var(--font-mono);
      font-size: 16px;
      padding: 6px 10px;
      outline: none;
      letter-spacing: 2px;
    }
    #mech-name-input:focus { border-bottom-color: var(--c-accent2); }

    /* ─── LB TYPE TOGGLE ─── */
    .toggle-group {
      display: flex; gap: 6px; margin-bottom: 10px;
    }
    .toggle-btn {
      flex: 1;
      font-family: var(--font-mono);
      font-size: 10px;
      padding: 5px 8px;
      background: var(--c-panel2);
      border: 1px solid var(--c-border);
      color: var(--c-muted);
      cursor: pointer;
      transition: all 0.15s;
      text-align: center;
    }
    .toggle-btn.active {
      background: rgba(18,148,131,0.2);
      border-color: var(--c-primary);
      color: var(--c-accent2);
    }

    /* ─── RADIO TIER ─── */
    .tier-row {
      display: flex; gap: 4px; flex-wrap: wrap; margin-top: 4px;
    }
    .tier-opt {
      font-family: var(--font-mono);
      font-size: 10px;
      padding: 3px 8px;
      background: var(--c-panel2);
      border: 1px solid var(--c-border);
      color: var(--c-muted);
      cursor: pointer;
      transition: all 0.12s;
    }
    .tier-opt.sel {
      background: rgba(18,148,131,0.2);
      border-color: var(--c-accent);
      color: var(--c-accent2);
    }

    /* ─── DISTANCE RANGE ─── */
    .range-pair {
      display: flex; gap: 8px; align-items: center; margin-top: 4px;
    }
    .range-pair input {
      width: 60px;
    }
    .range-pair span {
      font-family: var(--font-mono);
      font-size: 10px;
      color: var(--c-muted);
    }

    /* ─── TOAST ─── */
    #toast {
      position: fixed; bottom: 60px; left: 50%; transform: translateX(-50%);
      z-index: 999;
      background: rgba(18,148,131,0.9);
      color: var(--c-bg);
      font-family: var(--font-mono);
      font-size: 11px;
      padding: 8px 18px;
      letter-spacing: 1px;
      opacity: 0;
      transition: opacity 0.2s;
      pointer-events: none;
    }
    #toast.show { opacity: 1; }

    /* ─── MOBILE ─── */
    @media (max-width: 600px) {
      #ac-layout {
        grid-template-areas:
          "head"
          "ra"
          "la"
          "rb"
          "lb"
          "img"
          "core"
          "hands"
          "legs"
          "boost"
          "fcs"
          "engine"
          "ext";
        grid-template-columns: 1fr;
      }
      #ac-center img { max-height: 160px; }
      #walter-panel { width: 100%; right: -100%; }
      #walter-panel.open { right: 0; }
    }
    /* ─── PRESET CARDS ─── */
    #preset-list {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
      gap: 6px;
      margin-bottom: 10px;
    }
    .preset-card {
      background: var(--c-panel2);
      border: 1px solid var(--c-border);
      padding: 8px 10px;
      cursor: pointer;
      transition: all 0.15s;
      text-align: left;
      width: 100%;
    }
    .preset-card:hover {
      border-color: var(--c-primary);
      background: rgba(18,148,131,0.12);
    }
    .preset-card .pc-name {
      font-family: var(--font-mono);
      font-size: 11px;
      color: var(--c-white);
      letter-spacing: 1px;
      display: block;
      margin-bottom: 4px;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }
    .preset-card .pc-tags { display: flex; gap: 3px; flex-wrap: wrap; }
    .preset-card .pc-tag {
      font-family: var(--font-mono);
      font-size: 9px;
      color: var(--c-primary);
      border: 1px solid var(--c-border);
      padding: 1px 4px;
    }
    .preset-actions { display: flex; gap: 8px; margin-bottom: 16px; }
    .preset-actions .btn { flex: 1; font-size: 10px; padding: 6px 8px; }

    /* ─── IMPORT OVERLAY ─── */
    #import-overlay {
      position: fixed; inset: 0; z-index: 150;
      background: rgba(3,8,9,0.9);
      display: none; align-items: center; justify-content: center;
      backdrop-filter: blur(4px);
    }
    #import-overlay.open { display: flex; }
    #import-box {
      background: rgba(6,16,18,0.97);
      border: 1px solid var(--c-primary);
      width: min(90vw, 440px);
      display: flex; flex-direction: column;
    }
    #import-header {
      padding: 10px 14px;
      border-bottom: 1px solid var(--c-line);
      display: flex; align-items: center; justify-content: space-between;
    }
    #import-header span {
      font-family: var(--font-mono);
      font-size: 11px;
      color: var(--c-accent2);
      letter-spacing: 2px;
    }
    #import-header button {
      background: none; border: none; color: var(--c-muted);
      cursor: pointer; font-size: 14px; transition: color 0.15s; padding: 0 4px;
    }
    #import-header button:hover { color: var(--c-white); }
    #import-body { padding: 14px; }
    .import-tip {
      font-family: var(--font-mono);
      font-size: 10px;
      color: var(--c-muted);
      margin-bottom: 8px;
      letter-spacing: 1px;
    }
    #import-textarea {
      width: 100%;
      background: rgba(18,148,131,0.05);
      border: 1px solid var(--c-border);
      color: var(--c-white);
      font-family: var(--font-mono);
      font-size: 11px;
      padding: 8px;
      outline: none;
      resize: vertical;
    }
    #import-textarea:focus { border-color: var(--c-primary); }
    #import-footer {
      padding: 10px 14px;
      border-top: 1px solid var(--c-line);
      display: flex; justify-content: flex-end; gap: 8px;
    }

    /* ─── WALTER SIGN ─── */
    #walter-footer {
      flex-shrink: 0;
      padding: 12px 16px 14px;
      border-top: 1px solid rgba(30,74,74,0.5);
    }
    .walter-sign {
      font-family: 'Ma Shan Zheng', '华文行楷', cursive;
      font-size: 14px;
      color: var(--c-warn);
      line-height: 1.9;
      text-align: right;
      opacity: 0.88;
    }
    .walter-sign-attr {
      display: block;
      font-size: 12px;
      color: var(--c-muted);
      margin-top: 2px;
      font-family: 'Ma Shan Zheng', '华文行楷', cursive;
    }
  </style>
</head>
<body>

<div id="bg-layer"></div>
<div id="scanlines"></div>

<div id="app">
  <!-- TOP BAR -->
  <div id="topbar">
    <div id="topbar-title">
      ARMORED CORE VI <span>// GARAGE SYSTEM //</span>
      <span class="blink">_</span>
    </div>
    <div id="topbar-actions">
      <button class="btn-walter" onclick="toggleWalter()">
        [ 沃尔特 · 规则手册 ]
      </button>
    </div>
  </div>

  <!-- MAIN -->
  <div id="main">
    <div id="content">

      <!-- ══ PAGE 1: 驾驶员 ══ -->
      <div id="page-pilot" class="tab-page active">
        <div class="sec-header">
          驾驶员配置
          <span class="badge">PAGE 1 / 2</span>
        </div>

        <div class="form-grid">
          <div class="form-row">
            <label>资金 COAM</label>
            <input type="number" id="f-coam" value="5000" min="0" oninput="calcStats()">
          </div>
          <div class="form-row">
            <label>APM（操作每分钟）</label>
            <input type="number" id="f-apm" value="150" min="50" max="999" oninput="calcStats()">
          </div>
          <div class="form-row">
            <label>KRL 等级（1-10）</label>
            <input type="number" id="f-krl" value="1" min="1" max="10" oninput="calcStats()">
          </div>
        </div>

        <div class="sec-header">
          派生数值 <span class="badge">AUTO-CALC</span>
        </div>

        <div class="stat-grid">
          <div class="stat-item">
            <div class="stat-label">神经同步率 nSR</div>
            <div class="stat-val ok" id="d-nsr">55%</div>
          </div>
          <div class="stat-item">
            <div class="stat-label">驾驶加值</div>
            <div class="stat-val ok" id="d-drive">+2</div>
          </div>
          <div class="stat-item">
            <div class="stat-label">升级所需经验</div>
            <div class="stat-val" id="d-exp">100</div>
          </div>
          <div class="stat-item">
            <div class="stat-label">APM 档位</div>
            <div class="stat-val" id="d-apm-tier">受训</div>
          </div>
        </div>

        <div class="sec-header">KRL 等级说明</div>
        <div style="font-family: var(--font-mono); font-size: 10px; color: var(--c-muted); line-height: 1.9; margin-bottom: 20px; background: var(--c-panel2); border: 1px solid var(--c-border); padding: 10px;">
          <span style="color:var(--c-text);">KRL 1-2</span> 可基础神经同步 &nbsp;|&nbsp;
          <span style="color:var(--c-text);">KRL 3-4</span> 可感知护盾状态<br>
          <span style="color:var(--c-text);">KRL 5-6</span> 珂若尔护盾弹反激活 &nbsp;|&nbsp;
          <span style="color:var(--c-text);">KRL 7-8</span> 可感知友/敌珂若尔波动<br>
          <span style="color:var(--c-text);">KRL 9-10</span> 机甲如臂指使；珂若尔护盾弹反×1.5
        </div>

        <div style="display:flex; justify-content:flex-end;">
          <button class="btn btn-primary" onclick="switchTab('ac')">
            下一步：AC 配置 &gt;&gt;
          </button>
        </div>
      </div>

      <!-- ══ PAGE 2: AC 配置 ══ -->
      <div id="page-ac" class="tab-page">
        <div class="sec-header">
          AC 配置
          <span class="badge">PAGE 2 / 2</span>
        </div>

        <div id="mech-name-row">
          <label>AC 识别码</label>
          <input type="text" id="mech-name-input" placeholder="输入机甲名称..." maxlength="32" oninput="calcStats()">
        </div>

        <div id="ac-layout">
          <!-- HEAD -->
          <div id="slot-head">
            <button class="slot-btn" onclick="openSlot('头部')" id="btn-头部">
              <span class="slot-tag">[ 头部 ]</span>
              <span class="slot-name">— 未配置 —</span>
              <span class="slot-sub">先攻加值 +0 | 重量 0</span>
            </button>
          </div>
          <!-- RA -->
          <div id="slot-ra">
            <button class="slot-btn" onclick="openSlot('RA')" id="btn-RA">
              <span class="slot-tag">[ RA 右手武器 ]</span>
              <span class="slot-name">— 未配置 —</span>
              <span class="slot-sub">— | 重量 0</span>
            </button>
          </div>
          <!-- CENTER -->
          <div id="ac-center">
            <select id="ac-type-select" onchange="calcStats()">
              <option value="人形">人形机甲</option>
              <option value="逆足">逆足机甲</option>
              <option value="生物">生物机甲</option>
              <option value="球形">球形机甲</option>
              <option value="半履带">半履带机甲</option>
              <option value="多足">多足机甲</option>
            </select>
          </div>
          <!-- RB -->
          <div id="slot-rb">
            <button class="slot-btn" onclick="openSlot('RB')" id="btn-RB">
              <span class="slot-tag">[ RB 右肩武器 ]</span>
              <span class="slot-name">— 未配置 —</span>
              <span class="slot-sub">— | 重量 0</span>
            </button>
          </div>
          <!-- LA -->
          <div id="slot-la">
            <button class="slot-btn" onclick="openSlot('LA')" id="btn-LA">
              <span class="slot-tag">[ LA 左手武器 ]</span>
              <span class="slot-name">— 未配置 —</span>
              <span class="slot-sub">— | 重量 0</span>
            </button>
          </div>
          <!-- LB -->
          <div id="slot-lb">
            <button class="slot-btn" onclick="openSlot('LB')" id="btn-LB">
              <span class="slot-tag">[ LB 左肩 ]</span>
              <span class="slot-name">— 未配置 —</span>
              <span class="slot-sub">— | 重量 0</span>
            </button>
          </div>
          <!-- CORE -->
          <div id="slot-core">
            <button class="slot-btn" onclick="openSlot('核心')" id="btn-核心">
              <span class="slot-tag">[ 核心 ]</span>
              <span class="slot-name">— 未配置 —</span>
              <span class="slot-sub">装甲上限 0 | 重量 0</span>
            </button>
          </div>
          <!-- FCS -->
          <div id="slot-fcs">
            <button class="slot-btn" onclick="openSlot('FCS')" id="btn-FCS">
              <span class="slot-tag">[ FCS 武器管制 ]</span>
              <span class="slot-name">— 未配置 —</span>
              <span class="slot-sub">均衡战线型 | 重量 0</span>
            </button>
          </div>
          <!-- HANDS -->
          <div id="slot-hands">
            <button class="slot-btn" onclick="openSlot('手部')" id="btn-手部">
              <span class="slot-tag">[ 手部 ]</span>
              <span class="slot-name">— 未配置 —</span>
              <span class="slot-sub">近战加值 +0 | 重量 0</span>
            </button>
          </div>
          <!-- ENGINE -->
          <div id="slot-engine">
            <button class="slot-btn" onclick="openSlot('发动机')" id="btn-发动机">
              <span class="slot-tag">[ 发动机 ]</span>
              <span class="slot-name">— 未配置 —</span>
              <span class="slot-sub">总能源 0 | 重量 0</span>
            </button>
          </div>
          <!-- LEGS -->
          <div id="slot-legs">
            <button class="slot-btn" onclick="openSlot('足部')" id="btn-足部">
              <span class="slot-tag">[ 足部 ]</span>
              <span class="slot-name">— 未配置 —</span>
              <span class="slot-sub">移动效率 1 | 重量 0</span>
            </button>
          </div>
          <!-- BOOSTER -->
          <div id="slot-boost">
            <button class="slot-btn" onclick="openSlot('推进器')" id="btn-推进器">
              <span class="slot-tag">[ 推进器 ]</span>
              <span class="slot-name">— 未配置 —</span>
              <span class="slot-sub">总出力 100 | 重量 0</span>
            </button>
          </div>
          <!-- EXT -->
          <div id="slot-ext">
            <button class="slot-btn" onclick="openSlot('扩充机能')" id="btn-扩充机能">
              <span class="slot-tag">[ 扩充机能 ]</span>
              <span class="slot-name">— 未配置 —</span>
              <span class="slot-sub">无特殊效果</span>
            </button>
          </div>
        </div>

        <!-- INTEGRATED STATS -->
        <div class="sec-header">机体整合遥测 <span class="badge">REAL-TIME</span></div>
        <div id="integrated-stats">
          <div class="istat-row">
            <span class="istat-label">机体总重</span>
            <span class="istat-val" id="is-weight">0</span>
          </div>
          <div class="istat-row">
            <span class="istat-label">推重比</span>
            <span class="istat-val" id="is-pwr">— / —</span>
          </div>
          <div class="istat-row">
            <span class="istat-label">推重加值</span>
            <span class="istat-val" id="is-pwr-bonus">+0</span>
          </div>
          <div class="istat-row">
            <span class="istat-label">装甲值上限</span>
            <span class="istat-val" id="is-armor">0</span>
          </div>
          <div class="istat-row">
            <span class="istat-label">结构值上限</span>
            <span class="istat-val" id="is-struct">0</span>
          </div>
          <div class="istat-row">
            <span class="istat-label">ACS 值上限</span>
            <span class="istat-val" id="is-acs">0</span>
          </div>
          <div class="istat-row">
            <span class="istat-label">护盾容量上限</span>
            <span class="istat-val" id="is-shield">0</span>
          </div>
          <div class="istat-row">
            <span class="istat-label">先攻加值</span>
            <span class="istat-val" id="is-init">+0</span>
          </div>
        </div>

        <!-- MECH PRESETS -->
        <div class="sec-header">机甲预设 <span class="badge">PRESET LIBRARY</span></div>
        <div id="preset-list"><!-- JS渲染 --></div>
        <div class="preset-actions">
          <button class="btn btn-secondary" onclick="importPreset()">[ 导入预设 ]</button>
          <button class="btn btn-secondary" onclick="exportPreset()">[ 导出当前 ]</button>
        </div>

        <div style="display:flex; justify-content:space-between; gap:8px; margin-top:8px;">
          <button class="btn btn-secondary" onclick="switchTab('pilot')">&lt;&lt; 返回</button>
          <button class="btn btn-confirm" onclick="showConfirm()">///  确认出击  ///</button>
        </div>
      </div>

    </div>
  </div>

  <!-- BOTTOM NAV -->
  <div id="bottom-nav">
    <button class="nav-tab active" id="nav-pilot" onclick="switchTab('pilot')">
      PAGE 1<br>驾驶员配置
    </button>
    <button class="nav-tab" id="nav-ac" onclick="switchTab('ac')">
      PAGE 2<br>AC 配置
    </button>
  </div>
</div>

<!-- ══ WALTER NOTES PANEL ══ -->
<div id="walter-panel">
  <div id="walter-header">
    <h3>[ 沃尔特 · 战术手记 ]</h3>
    <button id="close-walter" onclick="toggleWalter()">&#10005;</button>
  </div>
  <div id="walter-tabs">
    <button class="w-tab active" onclick="switchWalterTab('weapon')">武器系统</button>
    <button class="w-tab" onclick="switchWalterTab('mech')">机甲类型</button>
    <button class="w-tab" onclick="switchWalterTab('shield')">护盾系统</button>
    <button class="w-tab" onclick="switchWalterTab('combat')">战斗规则</button>
  </div>
  <div id="walter-content">
    <!-- 武器系统 -->
    <div class="w-page active" id="wp-weapon">
      <div class="ref-block">
        <h4>武器 TIER 固定伤害（远程）</h4>
        <button class="copy-btn" onclick="copyRef('远程武器TIER伤害表:\nTIER1: 36 | TIER2: 63 | TIER3: 99\nTIER4: 153 | TIER5: 234 | TIER6: 324')">复制</button>
        <table class="ref-table">
          <tr><th>TIER</th><th>固定伤害</th><th>ACS积累(×1.0)</th></tr>
          <tr><td>TIER 1</td><td class="hl">36</td><td>~14</td></tr>
          <tr><td>TIER 2</td><td class="hl">63</td><td>~25</td></tr>
          <tr><td>TIER 3</td><td class="hl">99</td><td>~40</td></tr>
          <tr><td>TIER 4</td><td class="hl">153</td><td>~61</td></tr>
          <tr><td>TIER 5</td><td class="hl">234</td><td>~94</td></tr>
          <tr><td>TIER 6</td><td class="hl">324</td><td>~130</td></tr>
        </table>
      </div>
      <div class="ref-block">
        <h4>武器 TIER 固定伤害（近战，×1.8）</h4>
        <button class="copy-btn" onclick="copyRef('近战武器TIER伤害表:\nTIER1: 65 | TIER2: 113 | TIER3: 178\nTIER4: 275 | TIER5: 421 | TIER6: 583')">复制</button>
        <table class="ref-table">
          <tr><th>TIER</th><th>固定伤害</th></tr>
          <tr><td>TIER 1</td><td class="hl">65</td></tr>
          <tr><td>TIER 2</td><td class="hl">113</td></tr>
          <tr><td>TIER 3</td><td class="hl">178</td></tr>
          <tr><td>TIER 4</td><td class="hl">275</td></tr>
          <tr><td>TIER 5</td><td class="hl">421</td></tr>
          <tr><td>TIER 6</td><td class="hl">583</td></tr>
        </table>
      </div>
      <div class="ref-block">
        <h4>武器类型 ACS 积累修正</h4>
        <div class="ref-text">近战冲击  ×1.3
爆破武器  ×1.2
动能/能量 ×1.0
导弹      ×0.8
重击时    ×1.5</div>
      </div>
      <div class="ref-block">
        <h4>槽位说明</h4>
        <div class="ref-text">RA  右手 — 主力输出武器（步枪等）
LA  左手 — 手持武器/近战刃
RB  右肩 — 大型武装/导弹
LB  左肩 — 大型武装/导弹/护盾发生器</div>
      </div>
    </div>

    <!-- 机甲类型 -->
    <div class="w-page" id="wp-mech">
      <div class="ref-block">
        <h4>机甲类型参数</h4>
        <button class="copy-btn" onclick="copyRef('机甲类型参数:\n人形 机动±0 装甲TIER4 基准\n逆足 机动+3 装甲TIER3 高速机动\n生物 机动+1 装甲TIER4 免疫电磁 交感+30%\n球形 机动-2 装甲TIER6 全方位防御\n半履带 机动-1 装甲TIER5 远程投射+15%\n多足 机动+1 装甲TIER4 复杂地形免疫')">复制</button>
        <table class="ref-table">
          <tr><th>类型</th><th>机动</th><th>装甲潜力</th><th>特点</th></tr>
          <tr><td>人形</td><td>±0</td><td class="hl">TIER4</td><td>基准</td></tr>
          <tr><td>逆足</td><td class="hl">+3</td><td>TIER3</td><td>极限机动</td></tr>
          <tr><td>生物</td><td>+1</td><td>TIER4</td><td>免疫电磁 交感+30%</td></tr>
          <tr><td>球形</td><td>-2</td><td class="hl">TIER6</td><td>全方位防御</td></tr>
          <tr><td>半履带</td><td>-1</td><td class="hl">TIER5</td><td>投射+15%</td></tr>
          <tr><td>多足</td><td>+1</td><td>TIER4</td><td>地形免疫 挂载+30%</td></tr>
        </table>
      </div>
      <div class="ref-block">
        <h4>装甲/结构修正（相对人形基准）</h4>
        <div class="ref-text">球形   装甲×2.0  结构×0.5
逆足   装甲×0.7  结构×0.9
生物   装甲×0.8  结构×1.0
半履带 装甲×1.3  结构×1.1
多足   装甲×1.0  结构×1.05</div>
      </div>
      <div class="ref-block">
        <h4>推重比与加值</h4>
        <div class="ref-text">推重比 = 推进器总出力 ÷ 机体总重
推重加值 = floor(推重比), 最大+6

重装档 1.0-2.0  +1~+2
均衡档 2.1-4.5  +2~+4
突击档 4.6-7.0  +4~+6</div>
      </div>
    </div>

    <!-- 护盾系统 -->
    <div class="w-page" id="wp-shield">
      <div class="ref-block">
        <h4>脉冲护盾（Pulse Shield）</h4>
        <div class="ref-text">形态    大型矩形，重型正面守御
护盾量  高（150-300）
格挡    触发时拦截全部伤害
弹反    无
适合    重装均衡，正面承压</div>
      </div>
      <div class="ref-block">
        <h4>谐波护盾（Harmonic Shield）</h4>
        <div class="ref-text">形态    小型圆形，高响应机动
护盾量  中（80-150）
格挡    触发时正常拦截
弹反    Ⓓ1-2攻击时，护盾消耗×0.5反弹
适合    机动近战，游斗反制</div>
      </div>
      <div class="ref-block">
        <h4>珂若尔护盾（Coral Shield）</h4>
        <div class="ref-text">形态    球形光幕，360°全覆盖
护盾量  固定（由部件决定）
格挡    全方位拦截全部伤害
弹反    KRL 5-8: 消耗×0.5反弹
        KRL 9+:  消耗×0.75反弹
适合    中高KRL驾驶员</div>
      </div>
    </div>

    <!-- 战斗规则 -->
    <div class="w-page" id="wp-combat">
      <div class="ref-block">
        <h4>先攻公式</h4>
        <div class="ref-text">先攻 = d20 + 推重加值 + 驾驶加值 + 先攻加值</div>
      </div>
      <div class="ref-block">
        <h4>驾驶加值公式</h4>
        <button class="copy-btn" onclick="copyRef('驾驶加值 = round(APM/100) + round(nSR×6), 最大+12\nnSR = (50 + KRL×5)%')">复制</button>
        <div class="ref-text">nSR = (50 + KRL×5)%
驾驶加值 = round(APM/100) + round(nSR×6)
最大 +12</div>
      </div>
      <div class="ref-block">
        <h4>命中 vs 规避</h4>
        <div class="ref-text">攻方命中 = d20 + 驾驶加值 [+FCS区间+2]
守方规避 = d20 + 推重加值 + 驾驶加值
命中总值 > 防守总值 → 命中
超出10+ → 重击，伤害×1.5，ACS积累×1.5</div>
      </div>
      <div class="ref-block">
        <h4>甲弹对抗 TIER</h4>
        <div class="ref-text">武器TIER = 装甲TIER  → 平阶，削减装甲
武器TIER > 装甲TIER  → 穿透，直接打结构
武器TIER &lt; 装甲TIER  → 未击穿，伤害×10%</div>
      </div>
      <div class="ref-block">
        <h4>动作经济（每回合）</h4>
        <div class="ref-text">完整动作×1  弹幕/整备/全面电子战
快速动作×1  交火/移动/Blade Boost/快速电子战
反应×1      紧急规避/护盾格挡/近战招架</div>
      </div>
      <div class="ref-block">
        <h4>Ⓓ 距离档位</h4>
        <div class="ref-text">Ⓓ0  ~0M    贴脸，近战可用
Ⓓ1  ~500M  近战允许，Blade Boost连招
Ⓓ2  ~1000M 近程火力有效
Ⓓ3  ~1500M 中程交战
Ⓓ4+ 远程以上</div>
      </div>
    </div>
  </div>
  <div id="walter-footer">
    <div class="walter-sign">
      621，好好活着回来
      <span class="walter-sign-attr">——「指导手」沃尔特</span>
    </div>
  </div>
</div>

<!-- ══ SLOT MODAL ══ -->
<div id="modal-overlay" onclick="closeModalOnBg(event)">
  <div id="modal-box">
    <div id="modal-header">
      <span id="modal-title">部件配置</span>
      <button id="modal-close" onclick="closeModal()">&#10005;</button>
    </div>
    <div id="modal-body">
      <!-- Dynamic content rendered by JS -->
    </div>
    <div id="modal-footer">
      <button class="btn btn-secondary" onclick="clearSlot()">清空</button>
      <button class="btn btn-primary" onclick="saveSlot()">确认</button>
    </div>
  </div>
</div>

<!-- ══ CONFIRM OVERLAY ══ -->
<div id="confirm-overlay">
  <div id="confirm-text">
    <span class="big">/// MAIN SYSTEM //</span>
    <span>// COMBAT MODE ACTIVE //</span>
    <span class="sub" id="conf-mech-name">—</span>
  </div>
  <div id="confirm-preview"></div>
  <div id="confirm-btns">
    <button class="btn btn-secondary" onclick="hideConfirm()">取消</button>
    <button class="btn btn-confirm" onclick="deployAC()">
      ///  出击  ///
    </button>
  </div>
</div>

<!-- ══ IMPORT OVERLAY ══ -->
<div id="import-overlay" onclick="closeImport(event)">
  <div id="import-box">
    <div id="import-header">
      <span>[ 导入机甲预设 ]</span>
      <button onclick="closeImportBox()">&#10005;</button>
    </div>
    <div id="import-body">
      <p class="import-tip">粘贴从其他玩家处获取的机甲预设代码：</p>
      <textarea id="import-textarea" rows="8" placeholder="在此粘贴 JSON 预设代码..."></textarea>
    </div>
    <div id="import-footer">
      <button class="btn btn-secondary" onclick="closeImportBox()">取消</button>
      <button class="btn btn-primary" onclick="doImport()">确认导入</button>
    </div>
  </div>
</div>

<!-- ══ TOAST ══ -->
<div id="toast"></div>

<script>
'use strict';

// ═══════════════════════════════════════════════════════════
// DATA STORE
// ═══════════════════════════════════════════════════════════
const EXP_TABLE = [null, 100, 200, 400, 800, 1500, 3000, 6000, 12000, 25000];

const TYPE_MOD = {
  '人形':  { armor: 1.0,  struct: 1.0 },
  '逆足':  { armor: 0.7,  struct: 0.9 },
  '生物':  { armor: 0.8,  struct: 1.0 },
  '球形':  { armor: 2.0,  struct: 0.5 },
  '半履带': { armor: 1.3, struct: 1.1 },
  '多足':  { armor: 1.0,  struct: 1.05 },
};

const TYPE_MOBILITY = {
  '人形': 0, '逆足': 3, '生物': 1, '球形': -2, '半履带': -1, '多足': 1
};

// Part data keyed by slot id
const slots = {
  RA: null, LA: null, RB: null, LB: null,
  '头部': null, '核心': null, '手部': null, '足部': null,
  '推进器': null, 'FCS': null, '发动机': null, '扩充机能': null,
};

let activeSlot = null;

// ═══════════════════════════════════════════════════════════
// TAB NAVIGATION
// ═══════════════════════════════════════════════════════════
function switchTab(tab) {
  document.querySelectorAll('.tab-page').forEach(p => p.classList.remove('active'));
  document.querySelectorAll('.nav-tab').forEach(b => b.classList.remove('active'));
  document.getElementById('page-' + tab).classList.add('active');
  document.getElementById('nav-' + tab).classList.add('active');
  calcStats();
}

function switchWalterTab(tab) {
  document.querySelectorAll('.w-tab').forEach(b => b.classList.remove('active'));
  document.querySelectorAll('.w-page').forEach(p => p.classList.remove('active'));
  document.getElementById('wp-' + tab).classList.add('active');
  event.target.classList.add('active');
}

function toggleWalter() {
  document.getElementById('walter-panel').classList.toggle('open');
}

// ═══════════════════════════════════════════════════════════
// STAT CALCULATIONS
// ═══════════════════════════════════════════════════════════
function calcStats() {
  const apm = parseInt(document.getElementById('f-apm').value) || 150;
  const krl = Math.min(10, Math.max(1, parseInt(document.getElementById('f-krl').value) || 1));
  const nsr = 50 + krl * 5;
  const driveBonus = Math.min(12, Math.round(apm / 100) + Math.round(nsr / 100 * 6));
  const expNeeded = EXP_TABLE[krl] || 25000;
  const apmTier = apm < 150 ? '民兵' : apm < 250 ? '受训' : apm < 350 ? '精英' : apm < 450 ? '王牌' : '极限';

  setText('d-nsr', nsr + '%');
  setText('d-drive', '+' + driveBonus);
  setText('d-exp', expNeeded.toLocaleString());
  setText('d-apm-tier', apmTier);

  // Integrated mech stats
  const type = document.getElementById('ac-type-select').value;
  const mod = TYPE_MOD[type];

  let totalWeight = 0;
  Object.values(slots).forEach(s => { if (s) totalWeight += (s.重量 || 0); });

  const booster = slots['推进器'];
  const thrust = booster ? (booster.总出力 || 100) : 0;
  const pwrRatio = totalWeight > 0 ? thrust / totalWeight : 0;
  const pwrBonus = Math.min(6, Math.floor(pwrRatio));

  const core = slots['核心'];
  const baseArmor  = core ? (core.装甲上限 || 0) : 0;
  const baseStruct = core ? (core.结构上限 || 0) : 0;
  const baseACS    = core ? (core.ACS上限 || 0) : 0;
  const initBonus  = slots['头部'] ? (slots['头部'].先攻加值 || 0) : 0;

  const finalArmor  = Math.round(baseArmor  * mod.armor);
  const finalStruct = Math.round(baseStruct * mod.struct);

  const lb = slots['LB'];
  const shieldCap = (lb && lb.部件类型 === '护盾发生器') ? (lb.护盾上限 || 0) : 0;

  setText('is-weight', totalWeight);
  setText('is-pwr', totalWeight > 0 ? pwrRatio.toFixed(2) : '—');
  setText('is-pwr-bonus', '+' + pwrBonus);
  setText('is-armor', finalArmor);
  setText('is-struct', finalStruct);
  setText('is-acs', baseACS);
  setText('is-shield', shieldCap);
  setText('is-init', '+' + initBonus);
}

function setText(id, val) {
  const el = document.getElementById(id);
  if (el) el.textContent = val;
}

// ═══════════════════════════════════════════════════════════
// SLOT MODAL
// ═══════════════════════════════════════════════════════════
const SLOT_LABELS = {
  RA: 'RA 右手武器', LA: 'LA 左手武器', RB: 'RB 右肩武器', LB: 'LB 左肩',
  '头部': '头部', '核心': '核心', '手部': '手部', '足部': '足部',
  '推进器': '推进器', 'FCS': 'FCS 武器管制系统', '发动机': '发动机', '扩充机能': '扩充机能',
};

function openSlot(slot) {
  activeSlot = slot;
  document.getElementById('modal-title').textContent = '[ ' + SLOT_LABELS[slot] + ' ] 配置';
  document.getElementById('modal-body').innerHTML = buildModalForm(slot, slots[slot]);
  document.getElementById('modal-overlay').classList.add('open');
  // Restore LB toggle state
  if (slot === 'LB') {
    const current = slots.LB;
    const isShield = current && current.部件类型 === '护盾发生器';
    setLBType(isShield ? 'shield' : 'weapon');
  }
}

function buildModalForm(slot, data) {
  const d = data || {};
  const TIERS = ['TIER1','TIER2','TIER3','TIER4','TIER5','TIER6'];
  const WEAPON_TYPES = ['近战','动能','能量','爆破','导弹'];

  const tierPicker = (name, val) => `
    <div class="form-row">
      <label>${name}</label>
      <div class="tier-row" id="tier-${name}">
        ${TIERS.map(t => `<div class="tier-opt${val === t ? ' sel' : ''}" onclick="pickTier('${name}','${t}',this)">${t}</div>`).join('')}
      </div>
    </div>`;

  const weaponTypeSelect = (val) => `
    <div class="form-row">
      <label>武器类型</label>
      <select id="m-weapon-type">
        ${WEAPON_TYPES.map(t => `<option value="${t}"${val===t?' selected':''}>${t}</option>`).join('')}
      </select>
    </div>`;

  const distRange = (min, max) => `
    <div class="form-row">
      <label>FCS 最优距离区间 Ⓓ</label>
      <div class="range-pair">
        <input type="number" id="m-dist-min" value="${min||1}" min="0" max="9" placeholder="最小">
        <span>~</span>
        <input type="number" id="m-dist-max" value="${max||4}" min="0" max="9" placeholder="最大">
      </div>
    </div>`;

  const baseFields = `
    <div class="form-row"><label>部件名称</label>
      <input type="text" id="m-name" value="${d.部件名||d.武器名||d.护盾名||d.机能名||''}">
    </div>
    <div class="form-row"><label>制造商</label>
      <input type="text" id="m-maker" value="${d.制造商||''}">
    </div>
    <div class="form-row"><label>重量</label>
      <input type="number" id="m-weight" value="${d.重量||0}" min="0">
    </div>`;

  const weaponFields = (d2) => `
    ${weaponTypeSelect(d2.武器类型||'动能')}
    ${tierPicker('破甲等级', d2.破甲等级||'TIER1')}
    <div class="form-row"><label>固定伤害</label>
      <input type="number" id="m-dmg" value="${d2.固定伤害||0}" min="0">
    </div>
    <div class="form-row"><label>弹药量（0=无限/近战）</label>
      <input type="number" id="m-ammo" value="${d2.弹药量||0}" min="0">
    </div>
    ${distRange(d2.最优距离区间?.最小, d2.最优距离区间?.最大)}`;

  if (slot === 'RA' || slot === 'LA' || slot === 'RB') {
    return `<div class="form-grid">${baseFields}${weaponFields(d)}</div>`;
  }

  if (slot === 'LB') {
    const isShield = d.部件类型 === '护盾发生器';
    return `
      <div class="toggle-group">
        <div class="toggle-btn${!isShield?' active':''}" id="lb-weapon-btn" onclick="setLBType('weapon')">武器</div>
        <div class="toggle-btn${isShield?' active':''}" id="lb-shield-btn" onclick="setLBType('shield')">护盾发生器</div>
      </div>
      <div id="lb-weapon-form" style="display:${isShield?'none':'block'}">
        <div class="form-grid">${baseFields}${weaponFields(d)}</div>
      </div>
      <div id="lb-shield-form" style="display:${isShield?'block':'none'}">
        <div class="form-grid">
          ${baseFields}
          <div class="form-row"><label>护盾类型</label>
            <select id="m-shield-type">
              ${['脉冲护盾','谐波护盾','珂若尔护盾'].map(t=>`<option value="${t}"${d.护盾类型===t?' selected':''}>${t}</option>`).join('')}
            </select>
          </div>
          <div class="form-row"><label>护盾上限</label>
            <input type="number" id="m-shield-cap" value="${d.护盾上限||0}" min="0">
          </div>
        </div>
      </div>`;
  }

  if (slot === '头部') {
    return `<div class="form-grid">
      ${baseFields}
      <div class="form-row"><label>先攻加值</label>
        <input type="number" id="m-init" value="${d.先攻加值||0}" min="-5" max="10">
      </div>
    </div>`;
  }

  if (slot === '核心') {
    return `<div class="form-grid">
      ${baseFields}
      ${tierPicker('装甲等级', d.装甲等级||'TIER1')}
      <div class="form-row"><label>装甲上限</label>
        <input type="number" id="m-armor-cap" value="${d.装甲上限||100}" min="0">
      </div>
      <div class="form-row"><label>结构上限</label>
        <input type="number" id="m-struct-cap" value="${d.结构上限||100}" min="0">
      </div>
      <div class="form-row"><label>ACS 上限</label>
        <input type="number" id="m-acs-cap" value="${d.ACS上限||100}" min="0">
      </div>
    </div>`;
  }

  if (slot === '手部') {
    return `<div class="form-grid">
      ${baseFields}
      <div class="form-row"><label>近战伤害加值</label>
        <input type="number" id="m-melee" value="${d.近战伤害加值||0}" min="0">
      </div>
      <div class="form-row"><label>武器重量上限</label>
        <input type="number" id="m-wt-limit" value="${d.武器重量上限||50}" min="0">
      </div>
    </div>`;
  }

  if (slot === '足部') {
    return `<div class="form-grid">
      ${baseFields}
      <div class="form-row"><label>移动效率（Ⓓ/次）</label>
        <input type="number" id="m-move" value="${d.移动效率||1}" min="1" max="10">
      </div>
    </div>`;
  }

  if (slot === '推进器') {
    return `<div class="form-grid">
      ${baseFields}
      <div class="form-row"><label>总出力</label>
        <input type="number" id="m-thrust" value="${d.总出力||100}" min="0">
      </div>
    </div>`;
  }

  if (slot === 'FCS') {
    return `<div class="form-grid">
      ${baseFields}
      <div class="form-row"><label>战斗风格</label>
        <input type="text" id="m-fcs-style" value="${d.战斗风格||'均衡战线型'}">
      </div>
      ${distRange(d.最优距离区间?.最小, d.最优距离区间?.最大)}
      <div class="form-row" style="grid-column:1/-1"><label>特殊效果</label>
        <textarea id="m-fcs-effect" rows="3" style="resize:vertical">${d.特殊效果||''}</textarea>
      </div>
    </div>`;
  }

  if (slot === '发动机') {
    return `<div class="form-grid">
      ${baseFields}
      <div class="form-row"><label>总能源</label>
        <input type="number" id="m-energy" value="${d.总能源||100}" min="0">
      </div>
    </div>`;
  }

  if (slot === '扩充机能') {
    return `<div class="form-grid">
      <div class="form-row"><label>机能名称</label>
        <input type="text" id="m-ext-name" value="${d.机能名||''}">
      </div>
      <div class="form-row"><label>重量</label>
        <input type="number" id="m-weight" value="${d.重量||0}" min="0">
      </div>
      <div class="form-row" style="grid-column:1/-1"><label>效果描述</label>
        <textarea id="m-ext-effect" rows="4" style="resize:vertical">${d.效果描述||''}</textarea>
      </div>
    </div>`;
  }

  return '<p style="color:var(--c-muted);font-family:var(--font-mono);font-size:11px;">未知槽位</p>';
}

function setLBType(type) {
  const isShield = type === 'shield';
  document.getElementById('lb-weapon-form').style.display = isShield ? 'none' : 'block';
  document.getElementById('lb-shield-form').style.display = isShield ? 'block' : 'none';
  document.getElementById('lb-weapon-btn').classList.toggle('active', !isShield);
  document.getElementById('lb-shield-btn').classList.toggle('active', isShield);
}

let tierValues = {};
function pickTier(name, val, el) {
  tierValues[name] = val;
  el.closest('.tier-row').querySelectorAll('.tier-opt').forEach(o => o.classList.remove('sel'));
  el.classList.add('sel');
}

function closeModal() {
  document.getElementById('modal-overlay').classList.remove('open');
  activeSlot = null;
  tierValues = {};
}

function closeModalOnBg(e) {
  if (e.target === document.getElementById('modal-overlay')) closeModal();
}

function get(id, fallback) {
  const el = document.getElementById(id);
  if (!el) return fallback;
  return el.type === 'number' ? (parseFloat(el.value) || 0) : el.value.trim();
}

function saveSlot() {
  const slot = activeSlot;
  let data = null;

  if (slot === 'RA' || slot === 'LA' || slot === 'RB') {
    data = {
      部件类型: '武器',
      武器名: get('m-name', ''),
      武器类型: get('m-weapon-type', '动能'),
      破甲等级: tierValues['破甲等级'] || document.querySelector('#tier-破甲等级 .sel')?.textContent || 'TIER1',
      固定伤害: get('m-dmg', 0),
      弹药量: get('m-ammo', 0),
      最优距离区间: { 最小: get('m-dist-min', 1), 最大: get('m-dist-max', 4) },
      制造商: get('m-maker', ''),
      重量: get('m-weight', 0),
    };
  } else if (slot === 'LB') {
    const isShield = document.getElementById('lb-shield-btn').classList.contains('active');
    if (isShield) {
      data = {
        部件类型: '护盾发生器',
        护盾名: get('m-name', ''),
        护盾类型: get('m-shield-type', '脉冲护盾'),
        护盾上限: get('m-shield-cap', 0),
        制造商: get('m-maker', ''),
        重量: get('m-weight', 0),
      };
    } else {
      data = {
        部件类型: '武器',
        武器名: get('m-name', ''),
        武器类型: get('m-weapon-type', '导弹'),
        破甲等级: tierValues['破甲等级'] || document.querySelector('#tier-破甲等级 .sel')?.textContent || 'TIER1',
        固定伤害: get('m-dmg', 0),
        弹药量: get('m-ammo', 0),
        最优距离区间: { 最小: get('m-dist-min', 1), 最大: get('m-dist-max', 4) },
        制造商: get('m-maker', ''),
        重量: get('m-weight', 0),
      };
    }
  } else if (slot === '头部') {
    data = { 部件类型: '头部', 部件名: get('m-name',''), 制造商: get('m-maker',''), 重量: get('m-weight',0), 先攻加值: get('m-init',0) };
  } else if (slot === '核心') {
    data = {
      部件类型: '核心', 部件名: get('m-name',''), 制造商: get('m-maker',''), 重量: get('m-weight',0),
      装甲等级: tierValues['装甲等级'] || document.querySelector('#tier-装甲等级 .sel')?.textContent || 'TIER1',
      装甲上限: get('m-armor-cap',100), 结构上限: get('m-struct-cap',100), ACS上限: get('m-acs-cap',100),
    };
  } else if (slot === '手部') {
    data = { 部件类型: '手部', 部件名: get('m-name',''), 制造商: get('m-maker',''), 重量: get('m-weight',0), 近战伤害加值: get('m-melee',0), 武器重量上限: get('m-wt-limit',50) };
  } else if (slot === '足部') {
    data = { 部件类型: '足部', 部件名: get('m-name',''), 制造商: get('m-maker',''), 重量: get('m-weight',0), 移动效率: get('m-move',1) };
  } else if (slot === '推进器') {
    data = { 部件类型: '推进器', 部件名: get('m-name',''), 制造商: get('m-maker',''), 重量: get('m-weight',0), 总出力: get('m-thrust',100) };
  } else if (slot === 'FCS') {
    data = { 部件类型: 'FCS', 部件名: get('m-name',''), 制造商: get('m-maker',''), 重量: get('m-weight',0), 战斗风格: get('m-fcs-style','均衡战线型'), 最优距离区间: { 最小: get('m-dist-min',1), 最大: get('m-dist-max',4) }, 特殊效果: get('m-fcs-effect','') };
  } else if (slot === '发动机') {
    data = { 部件类型: '发动机', 部件名: get('m-name',''), 制造商: get('m-maker',''), 重量: get('m-weight',0), 总能源: get('m-energy',100) };
  } else if (slot === '扩充机能') {
    data = { 部件类型: '扩充机能', 机能名: get('m-ext-name',''), 效果描述: get('m-ext-effect',''), 重量: get('m-weight',0) };
  }

  if (data) {
    slots[slot] = data;
    updateSlotButton(slot, data);
    calcStats();
  }
  closeModal();
  showToast('已保存 ' + SLOT_LABELS[slot]);
}

function clearSlot() {
  slots[activeSlot] = null;
  updateSlotButton(activeSlot, null);
  calcStats();
  closeModal();
  showToast('已清空 ' + SLOT_LABELS[activeSlot]);
}

function updateSlotButton(slot, data) {
  const btn = document.getElementById('btn-' + slot);
  if (!btn) return;
  const nameEl = btn.querySelector('.slot-name');
  const subEl  = btn.querySelector('.slot-sub');
  if (!data) {
    nameEl.textContent = '— 未配置 —';
    subEl.textContent = '—';
    btn.classList.remove('filled');
    return;
  }
  btn.classList.add('filled');
  const displayName = data.武器名 || data.护盾名 || data.部件名 || data.机能名 || '已配置';
  nameEl.textContent = displayName || '已配置';

  if (data.部件类型 === '武器') {
    subEl.textContent = (data.武器类型||'') + ' TIER ' + (data.破甲等级||'').replace('TIER','') + ' | 重量 ' + (data.重量||0);
  } else if (data.部件类型 === '护盾发生器') {
    subEl.textContent = (data.护盾类型||'') + ' | 重量 ' + (data.重量||0);
  } else if (data.部件类型 === '头部') {
    subEl.textContent = '先攻加值 +' + (data.先攻加值||0) + ' | 重量 ' + (data.重量||0);
  } else if (data.部件类型 === '核心') {
    subEl.textContent = '装甲上限 ' + (data.装甲上限||0) + ' | 重量 ' + (data.重量||0);
  } else if (data.部件类型 === '手部') {
    subEl.textContent = '近战 +' + (data.近战伤害加值||0) + ' | 重量 ' + (data.重量||0);
  } else if (data.部件类型 === '足部') {
    subEl.textContent = '移动效率 ' + (data.移动效率||1) + ' | 重量 ' + (data.重量||0);
  } else if (data.部件类型 === '推进器') {
    subEl.textContent = '总出力 ' + (data.总出力||100) + ' | 重量 ' + (data.重量||0);
  } else if (data.部件类型 === 'FCS') {
    subEl.textContent = (data.战斗风格||'') + ' | 重量 ' + (data.重量||0);
  } else if (data.部件类型 === '发动机') {
    subEl.textContent = '总能源 ' + (data.总能源||100) + ' | 重量 ' + (data.重量||0);
  } else if (data.部件类型 === '扩充机能') {
    subEl.textContent = data.效果描述 ? data.效果描述.slice(0, 20) + '...' : '无特殊效果';
  }
}

