// CONFIRM OVERLAY
// ═══════════════════════════════════════════════════════════
function buildVarObject() {
  const apm = parseInt(document.getElementById('f-apm').value) || 150;
  const krl = Math.min(10, Math.max(1, parseInt(document.getElementById('f-krl').value) || 1));
  const coam = parseInt(document.getElementById('f-coam').value) || 0;
  const nsr = 50 + krl * 5;
  const driveBonus = Math.min(12, Math.round(apm / 100) + Math.round(nsr / 100 * 6));
  const expNeeded = EXP_TABLE[krl] || 25000;
  const mechName = document.getElementById('mech-name-input').value.trim() || '未命名';
  const type = document.getElementById('ac-type-select').value;
  const mod = TYPE_MOD[type];

  let totalWeight = 0;
  Object.values(slots).forEach(s => { if (s) totalWeight += (s.重量 || 0); });
  const thrust = slots['推进器'] ? (slots['推进器'].总出力 || 100) : 0;
  const pwrRatio = totalWeight > 0 ? parseFloat((thrust / totalWeight).toFixed(2)) : 0;
  const pwrBonus = Math.min(6, Math.floor(pwrRatio));
  const core = slots['核心'];
  const baseArmor  = core ? (core.装甲上限  || 0) : 0;
  const baseStruct = core ? (core.结构上限  || 0) : 0;
  const baseACS    = core ? (core.ACS上限   || 0) : 0;
  const armorTier  = core ? (core.装甲等级  || 'TIER1') : 'TIER1';
  const initBonus  = slots['头部'] ? (slots['头部'].先攻加值 || 0) : 0;
  const finalArmor  = Math.round(baseArmor  * mod.armor);
  const finalStruct = Math.round(baseStruct * mod.struct);
  const lb = slots['LB'];
  const shieldCap = (lb && lb.部件类型 === '护盾发生器') ? (lb.护盾上限 || 0) : 0;

  const buildParts = {};
  Object.entries(slots).forEach(([k, v]) => { if (v) buildParts[k] = v; });

  return {
    meta: { apm, krl, nsr, driveBonus, expNeeded, coam, mechName, type, totalWeight, pwrRatio, pwrBonus, finalArmor, finalStruct, baseACS, shieldCap, initBonus, armorTier },
    varData: {
      主角: {
        驾驶属性: { APM: apm, KRL等级: krl, 神经同步率: nsr, 驾驶加值: driveBonus },
        机甲状态: {
          结构值: finalStruct, 结构上限: finalStruct,
          装甲值: finalArmor,  装甲上限: finalArmor,
          ACS值: 0,            ACS上限: baseACS,
          护盾值: shieldCap,   护盾上限: shieldCap,
        },
        驾驶员档案: { 资金_CAGE: coam, 当前经验: 0, 升级所需经验: expNeeded },
      },
      机甲泊位: {
        当前驾驶机甲: mechName,
        泊位: {
          [mechName]: {
            部件构建: buildParts,
            机体整合数值: {
              机体类型: type, 装甲等级: armorTier,
              装甲上限: finalArmor, 结构上限: finalStruct, ACS上限: baseACS,
              护盾上限: shieldCap, 机体总重: totalWeight,
              推重比: pwrRatio, 推重加值: pwrBonus, 先攻加值: initBonus,
            },
          },
        },
      },
    },
  };
}

