async function deployAC() {
  const { meta, varData } = buildVarObject();
  hideConfirm();

  const patches = buildPatches(varData);

  // Build and send start message with embedded MVU initialization patches
  const msg = [
    `机甲识别码: ${meta.mechName}`,
    `机体类型: ${meta.type}  |  驾驶员APM: ${meta.apm}  |  KRL: ${meta.krl}  |  nSR: ${meta.nsr}%`,
    `装甲: ${meta.finalArmor}  结构: ${meta.finalStruct}  ACS上限: ${meta.baseACS}  护盾: ${meta.shieldCap}`,
    `武装 [RA]${slots.RA?(slots.RA.武器名||'—'):'—'} [LA]${slots.LA?(slots.LA.武器名||'—'):'—'} [RB]${slots.RB?(slots.RB.武器名||'—'):'—'} [LB]${slots.LB?(slots.LB.武器名||slots.LB.护盾名||'—'):'—'}`,
    ``,
    `初始化完成，开始任务。`,
    ``,
    `<UpdateVariable>`,
    `<Analysis>System initialized. Pilot and AC configuration registered. All combat parameters locked. Entering combat mode.</Analysis>`,
    `<JSONPatch>`,
    JSON.stringify(patches, null, 2),
    `</JSONPatch>`,
    `</UpdateVariable>`,
  ].join('\n');

  // 直接注入 ST 聊天框（保守方式，与旧版一致）
  const parentDoc = window.parent ? window.parent.document : document;
  const stTextarea = parentDoc.getElementById('send_textarea');
  if (stTextarea) {
    const nativeSetter = Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype, 'value').set;
    nativeSetter.call(stTextarea, msg);
    stTextarea.dispatchEvent(new Event('input', { bubbles: true }));
    stTextarea.focus();
    showToast('已载入聊天框 — 按 Enter 出击');
  } else {
    // 后备：复制到剪贴板
    navigator.clipboard.writeText(msg)
      .then(() => showToast('已复制到剪贴板，请粘贴到聊天框发送'))
      .catch(() => showToast('请手动复制消息内容'));
  }
}

