function renderPresets() {
  const container = document.getElementById('preset-list');
  if (!container) return;
  container.innerHTML = BUILTIN_PRESETS.map((p, i) => `
    <button class="preset-card" onclick="loadPreset(BUILTIN_PRESETS[${i}])">
      <span class="pc-name">${p.name}</span>
      <div class="pc-tags">
        <span class="pc-tag">${p.type}</span>
        ${p.tags.map(t => `<span class="pc-tag">${t}</span>`).join('')}
      </div>
    </button>
  `).join('');
}

function loadPreset(preset) {
  Object.keys(slots).forEach(k => { slots[k] = null; });
  Object.assign(slots, JSON.parse(JSON.stringify(preset.slots)));
  document.getElementById('mech-name-input').value = preset.name;
  document.getElementById('ac-type-select').value = preset.type;
  Object.keys(slots).forEach(k => updateSlotButton(k, slots[k]));
  calcStats();
  showToast('已载入预设: ' + preset.name);
}

function exportPreset() {
  const name = document.getElementById('mech-name-input').value.trim() || '未命名';
  const type = document.getElementById('ac-type-select').value;
  if (!Object.values(slots).some(v => v !== null)) { showToast('当前无配置可导出'); return; }
  const exportData = { ac6_preset_v1: true, name, type, slots: JSON.parse(JSON.stringify(slots)) };
  const json = JSON.stringify(exportData, null, 2);
  navigator.clipboard.writeText(json)
    .then(() => showToast('预设已复制到剪贴板'))
    .catch(() => {
      const ta = document.createElement('textarea');
      ta.value = json; document.body.appendChild(ta); ta.select();
      document.execCommand('copy'); document.body.removeChild(ta);
      showToast('预设已复制');
    });
}

function importPreset() {
  document.getElementById('import-textarea').value = '';
  document.getElementById('import-overlay').classList.add('open');
}

function closeImportBox() {
  document.getElementById('import-overlay').classList.remove('open');
}

function closeImport(e) {
  if (e.target === document.getElementById('import-overlay')) closeImportBox();
}

function doImport() {
  const text = document.getElementById('import-textarea').value.trim();
  try {
    const data = JSON.parse(text);
    if (!data.ac6_preset_v1 || typeof data.slots !== 'object') throw new Error('格式不匹配');
    loadPreset(data);
    closeImportBox();
  } catch(e) {
    showToast('导入失败: ' + e.message);
  }
}

// ═══════════════════════════════════════════════════════════
// INIT
// ═══════════════════════════════════════════════════════════
document.addEventListener('DOMContentLoaded', () => {
  calcStats();
  renderPresets();
});
</script>
